WITH payload AS (SELECT $archive_payload$[{"id":"8a7051b6-287f-5f06-af97-d60fa1a2604c","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة وأوالده -طلب النفقة املستقبلية ابتداء من","document_number":"33353081","case_number":"3394242","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":"الدائرة تقرر ما يلي :أوال :املوافقة على رجوع فضيلته عما حكم به","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/22","year":"1434","subject":"نفقة -نفقة زوجة وأوالده -طلب النفقة املستقبلية ابتداء من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/22 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33353081 :‬‬\n                    ‫َر ْق ُم الدعوى‪3394242 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 3491365‬تاريخه‪1434/1/26 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة وأوالده ‪ -‬طلــب النفقــة املســتقبلية ابتــداء مــن‬\n‫تاريــخ تقــدمي الدعــوى‪ -‬تقريــر انعقــاد االختصــاص احمللــي‪ -‬احلضانــة‬\n‫تثبــت لــأم ولــو كانــت الزوجيــة قائمــة‪ -‬النفقــة تســلم للحاضنــة‪-‬‬\n‫تنــازل الزوجــة عــن املطالبــة بنفقتهــا المتناعهــا عــن حلــف اليمــن‬\n‫علــى عــدم النشــوز‪ -‬احلكــم علــى األب بدفــع نفقــة األوالد املســتقبلية ‪.‬‬\n\n\n\n\n                                  ‫‪ -1‬قولة تعالى ( لينفق ذو سعه من سعته )‬\n‫‪ -2‬مــا جــاء يف اإلقنــاع وشــرحه مــن كشــاف القنــاع ( فــإذا افتــرق‬\n‫الزوجــان ولهمــا طفــل أو معتــوه أو مجنــون ذكــر أو أنثــى فأحــق النــاس‬\n                                           ‫بحضانتــه أمــه كمــا قبــل الفــراق)‬\n‫‪ -3‬قــال يف املغنــي ( فأمــا إذا كان لــه منهــا ولــد فعليــه نفقــه ولــده ألنهــا‬\n‫واجبــة لــه فــا يســقط حقــه مبعصيتهــا كالكبيــر وعليــه أن يعطيهــا‬\n                             ‫إياهــا إذا كانــت هــي احلاضنــة لــه أو املرضعــة)‬\n‫‪ -4‬قــال يف كشــاف القنــاع ‪( 443/3‬وينفــق احلاكــم عليــه أي املفلــس‬\n‫وعلــى مــن تلزمــه نفقتــه مــن زوجــة وخــادم وقريــب ألنهــم يجــرون‬\n‫مجــرى نفســه مــن مالــه باملعــروف لقولــة صلــى اهلل عليــه وســلم ابــدأ‬\n         ‫بنفســك ثــم مبــن تعــول وألن ملكــه بــاق عليــه قبــل القســمة)‬\n                    ‫‪ -5‬املادة ‪ 7/217‬من نظام املرافعات ولوائحه التنفيذية‬\n\n                                                                                        ‫‪88‬‬\n\f                       ‫‪ -6‬املواد ‪192‬و‪193‬و‪195‬و‪ 2‬من نظام املرافعات الشرعية‬\n\n\n\n\n     ‫ادعــى املدعــي وكالــة بــأن موكلتــه زوجــة للمدعــى عليــه ومــا زالــت‬\n     ‫يف عصمتــه واجنبــت منــه ابنــن وبنت ـ ًا وذكــر أعمارهــم‪ ،‬وأن األوالد‬\n     ‫يقيمــون مــع والدتهــم عنــد والدهــا واملدعــى عليــه ال ينفــق عليهــم‪ ،‬طلــب‬\n     ‫املدعــى وكالــة إلــزام املدعــى عليــه بدفــع النفقــة املســتقبلية ملوكلتــه‬\n     ‫وأوالدهــا منــه ابتــداء مــن تاريــخ تقــدمي الدعــوى‪ ،‬صــادق املدعــى عليــه‬\n     ‫علــى الزوجيــة واإلجنــاب وأن املدعيــة عنــد والدهــا‪ ،‬ودفــع بــأن أوالده‬\n     ‫عنــده يف منزلــه يف قريتــه ويف اإلجــازات يرجعــون معــه إلــى احملافظــة‬\n     ‫وأنــه ينفــق عليهــم النفقــة الواجبــة‪ ،‬دفــع املدعــى عليــه بــأن املدعيــة‬\n     ‫ناشــز وال تســتحق النفقــة‪ ،‬أنكــر املدعــي وكالــة مــا دفــع بــه املدعــى‬\n     ‫عليــه‪ ،‬أحضــر املدعــي وكالــة بينتــه املعدلــة التــي شــهدت بحضانــة‬\n     ‫املدعيــة ألوالدهــا وأنهــا هــي التــي تنفــق عليهــم‪ ،‬جــرى تقديــر نفقــة‬\n     ‫املدعيــة وأوالدهــا مــن قبــل هيئــة النظــر‪ ،‬حيــث إن األصــل عــدم النشــوز‬\n     ‫واحلضانــة تثبــت لــأم ولــو كانــت الزوجيــة قائمــة وعلــى األب أن يســلم‬\n     ‫النفقــة لــأم إذا كانــت هــي احلاضنــة كمــا قــرره الفقهــاء‪ ،‬لــذا صــدر‬\n     ‫احلكــم علــى املدعــى عليــه بــأن يســلم للمدعيــة أصالــة النفقــة املســتقبلية‬\n     ‫لهــا وألوالدهــا املذكوريــن حســبما جــاء يف قــرار هيئــة النظــر‪ ،‬لوحــظ‬\n     ‫علــى احلكــم مــن محكمــة االســتئناف بــأن املدعــى عليــه ذكــر يف‬\n     ‫الئحتــه االعتراضيــة أن لديــه البينــة علــى نشــوز املدعيــة‪ ،‬قــرر املدعــى‬\n     ‫وكالــة بــأن موكلتــه متنازلــة عــن دعواهــا بالنفقــة‪ ،‬رجــع القاضــي‬\n     ‫عــن احلكــم بالنفقــة املســتقبلية للزوجــة املدعيــة‪ ،‬صــدق احلكــم مــن‬\n‫‪89‬‬\n\f‫محكمــة االســتئناف‪ ،‬قــدم املدعــى عليــه التمــاس حملكمة االســتئناف‬\n                                                           ‫ومت رفضــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بعنيــزة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعنيــزة برقــم ‪ 3394242‬وتاريــخ ‪1433/02/07‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 33245592‬وتاريــخ ‪1433/02/07‬ه ـ بشــأن دعــوى ‪...‬ضــد ‪...‬يف‬\n‫نفقــة ففــي يــوم الثالثــاء املوافــق‪ 1433/03/15‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة والنصــف صباحــا وفيهــا حضــر ‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬بصفتــه وكيــا عــن ‪ ...‬مبوجب الوكالة‬\n‫الصــادرة مــن كتابــة عــدل محافظــة الــرس برقــم ‪ 860605005033‬يف‬\n‫‪1432/7/16‬ه ـ ولــم يحضــر املدعــى عليــه وقــد تبلــغ لشــخصه مبوعــد‬\n‫جلســة اليــوم ولذلــك فقــد أذنــت للمدعــي بتحريــر دعــواه فادعــى قائــا‬\n‫إننــي أدعــى علــى املدعــى عليــه الغائــب ‪...‬بــأن موكلتــي ‪ ...‬تزوجــت بــه‬\n‫وأجنبــت منــه ابنــن وبنــت وهــم ‪...‬وعمــره تســع ســنوات و‪...‬وعمــره ســت‬\n‫ســنوات و‪ ...‬وعمرهــا ثــاث ســنوات وهــم يقيمــون معهــا عنــد والدهــا‬\n‫منــذ ‪1430/8/1‬ه ـ وهــو ال ينفــق عليهــم لــذا أطلــب إلزامــه بالنفقــة‬\n‫املســتقبلية علــى موكلتــي وأوالدهــا مــن املدعــى عليــه املذكوريــن‬\n‫ابتــداء مــن تاريــخ تقــدمي الدعــوى يف ‪1433/2/7‬ه ـ هــذه دعــواي ثــم‬\n‫رفعــت اجللســة وحــددت اجللســة القادمــة يف يــوم الثالثــاء املوافــق‬\n‫‪1433/4/13‬ه ـ الســاعة الثامنــة صباحــا وعليــه حصــل التوقيــع ويف‬\n‫يــوم الثالثــاء املوافــق‪ 1433/04/13‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n\n                                                                                     ‫‪90‬‬\n\f     ‫صباحــا وفيهــا حضــر املدعــي وكالــة وقــد وردتنــا ورقــة تبليــغ املدعــى‬\n     ‫عليــه بجلســة اليــوم وقــد وقــع عليهــا املدعــى عليــه بشــخصه واعتــذر عــن‬\n     ‫احلضــور يف خطــاب أرفــق باملعاملــة بحجــة أنــه يعمــل يف ضريــة ويســكن‬\n     ‫أيــام العمــل يف ضريــة ويطلــب حتويــل معاملتــه إلــى احملكمــة العامــة‬\n     ‫يف ضريــة ونظــرا إلــى أن املدعــى عليــه قــد قــرر يف إقــراره املــؤرخ يف‬\n     ‫‪1433/1/24‬ه ـ أن منزلــه احلالــي الــذي يســكن فيــه مــع زوجتــه الثانيــة‬\n     ‫يف محافظــة عنيــزة وأنــه يعمــل وكيــا ملدرســة ‪ ...‬التــي تتبــع لضريــة‬\n     ‫وأنــه يرغــب حتويــل قضيتــه إلــى مقــر ســكنه عنيــزة وهــذا اإلقــرار‬\n     ‫طلــب بــه حتويــل دعــوى رفعتهــا عليــه املدعيــة أصالــة لــدى محكمــة‬\n     ‫أبانــات فطلــب حتويلهــا إلــى محكمــة عنيــزة يف هــذا اإلقــرار ووردت‬\n     ‫تلــك الدعــوى مــن محكمــة أبانــات وأحيلــت إلينــا مــن الرئيــس برقــم‬\n     ‫‪ 3376018‬يف ‪1433/1/30‬ه ـ وهــي ال تــزال منظــورة لدينــا ولكــون‬\n     ‫املدعــى عليــه قــد أقــر بــأن مقــر ســكنه عنيــزة وليــس بــن إقــراره وبــن‬\n     ‫تقــدمي هــذه الدعــوى التــي بــن أيدينــا ســوى ثالثــة عشــر يومــا ولذلــك‬\n     ‫فقــد قــررت مواصلــة النظــر يف الدعــوى النعقــاد االختصــاص احمللــي‬\n     ‫حملكمــة عنيــزة مبوجــب إقــرار املدعــى عليــه وقــررت مخاطبــة هيئــة‬\n     ‫النظــر لتقديــر النفقــة وحــددت اجللســة القادمــة يف يــوم الثالثــاء املوافــق‬\n     ‫‪1433/5/18‬ه ـ الســاعة التاســعة صباحــا وعليــه حصــل التوقيــع ويف يوم‬\n     ‫الثالثــاء املوافــق‪ 1433/05/18‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n     ‫صباحــا وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه ‪...‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪...‬وقــد جــرى عــرض دعــوى املدعــي وكالــة‬\n     ‫علــى املدعــى عليــه فأجــاب بقولــه أمــا مــا ذكــره املدعــي وكالــة مــن‬\n     ‫زواجــي مبوكلتــه وإجنابهــا األوالد املذكوريــن منــي وأنهــا تقيــم حاليـ ًا‬\n\n\n‫‪91‬‬\n\f‫عنــد والدهــا فهــذا صحيــح وتاريــخ خروجهــا مــن بيتــي إلــى والدهــا يف‬\n‫أواخــر شــهر ثمانيــة مــن عــام ألــف وأربعمائــة وثالثــة وثالثــن للهجــرة‬\n‫وأمــا مــا ذكــره مــن أن أوالدي املذكوريــن منهــا يقيمــون معهــا عنــد‬\n‫والدهــا وأننــي ال أنفــق عليهــم فهــذا غيــر صحيــح فــأوالدي املذكــورون‬\n‫عنــدي يف منزلــي الواقــع يف ‪ .....‬القريــب مــن عملــي ومــن املنــزل الــذي‬\n‫تقيــم فيــه املدعيــة أصالــة مــع والدهــا ويف اإلجــازات يرجعــون معــي إلــى‬\n‫عنيــزة وأنــا الــذي أنفــق عليهــم النفقــة الواجبــة وهــم يف رعايتــي وحتــت‬\n‫حضانتــي وأمــا املدعيــة أصالــة فهــي ناشــز وقــد خرجــت بيــت والدهــا‬\n‫بــدون إذنــي ولذلــك فــا نفقــة لهــا علــي وأطلــب رد دعــوى املدعــي وكالــة‬\n‫هكــذا أجــاب املدعــى عليــه وبعــرض جوابــه علــى املدعــي وكالــة أجاب‬\n‫بقولــه مــا دفــع بــه املدعــى عليــه مــن أن موكلتــي خرجــت بــدون إذنــه‬\n‫وأنهــا ناشــز فهــذا غيــر صحيــح والصحيــح أنــه هــو الــذي أخرجهــا مــن‬\n‫بيتــه يف تاريــخ ‪1430/8/1‬ه ـ وقــال لهــا اذهبــي ألهلــك وورقــة الطــاق‬\n‫تأتيــك ولــم يعدهــا إليــه حتــى اآلن ولــم يطلقهــا ومــا دفــع املدعــى عليــه‬\n‫مــن أنــه هــو الــذي ينفــق علــى أوالده املذكوريــن فهــذا غيــر صحيــح إذ‬\n‫أنهــم يف حضانــة والدتهــم موكلتــي منــذ أخرجهــا مــن بيتــه حتــى اآلن‬\n‫ولــم ينفــق عليهــم شــيئ ًا وكيــف يجلســون معــه وهــم صغــار لوحدهــم‬\n‫يف بيتــه يف ‪ .....‬هكــذا أجــاب وقــد ســألت املدعــى عليــه أيــن أوالده‬\n‫حاليـ ًا فقــال إنهــم عنــد أمهــم حاليـ ًا يف بيــت والدهــا وذلــك ألننــي منشــغل‬\n‫بهــذه اجللســة هكــذا أجــاب وقــد ســألت املدعــي مــن الــذي يرعــى‬\n‫أوالده املذكوريــن إذا خــرج حلاجاتــه أو خــرج إلــى عملــه فقــال إننــي قــد‬\n‫أحضــرت خادمــة لهــم ترعاهــم إذا كانــوا يف البيــت كمــا أن املنــزل‬\n‫الــذي وفرتــه لهــم قريــب مــن املنــزل الــذي تقيــم فيــه املدعيــة أصالــة مــع‬\n\n\n                                                                                        ‫‪92‬‬\n\f     ‫والدهــا فبينهمــا خمســون متــرا فقــط وهــم يخرجــون لزيارتهــا ويرجعــون‬\n     ‫إلــي وأحيانـ ًا يبيتــون عندهــا ولكنــي ملتــزم بالنفقــة عليهــم بنفســي وال‬\n     ‫صحــة ملــا ذكــره املدعــي وكالــة يف جوابــه علــى دفعــي مــن أننــي أنــا‬\n     ‫الــذي أخرجــت موكلتــه مــن بيتــي أو أنهــا هــي التــي تنفــق عليهــم هكذا‬\n     ‫أجــاب وقــد ســألت املدعــي وكالــة عــن بينتــه علــى أن املدعيــة هــي التــي‬\n     ‫تنفــق علــى أوالدهــا املذكوريــن وأنهــم يقيمــون عندهــا فقــال نعــم لــدي‬\n     ‫بينــة علــى ذلــك وســوف أحضرهــا يف اجللســة القادمــة ورفعــت اجللســة‬\n     ‫لذلــك وحــددت اجللســة القادمــة يف يــوم األربعــاء املوافــق ‪1433/6/18‬ه ـ‬\n     ‫الســاعة التاســعة صباح ـ ًا ويف يــوم األربعــاء املوافق‪1433/06/18‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة التاســعة صباحــا وفيهــا حضــر املدعــي وكالــة‬\n     ‫ولــم يحضــر املدعــى عليــه وقــد أحضــر املدعــي وكالــة بينتــه التــي وعــد‬\n     ‫بإحضارهــا وهــم الشــاهد ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ ...‬والشــاهد ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n     ‫وطلــب املدعــي وكالــة ســماع شــهادتهما وبســؤالهما عمــا لديهمــا مــن‬\n     ‫شــهادة شــهد كل واحــد منهمــا قائــا أشــهد أن كال مــن ‪ ...‬و‪ ...‬و‪...‬‬\n     ‫أوالد املدعيــة ‪...‬مــن املدعــى عليــه ‪ ...‬يقيمــون مــع أمهــم املدعيــة عنــد‬\n     ‫جدهــم ألمهــم يف ‪ .....‬وهــم يف حضانتهــا منــذ حصــول املشــكلة بينهــا‬\n     ‫وبــن زوجهــا املدعــى عليــه يف شــهر ثمانيــة مــن عــام ‪1430‬ه ـ وحتــى‬\n     ‫اآلن هكــذا شــهد كل واحــد منهمــا وقــد طلبــت مــن املدعــي وكالــة‬\n     ‫إحضــار معدلــن للشــاهدين فطلــب املهلــة لذلــك فأمهلتــه إلــى يــوم‬\n     ‫الثالثــاء املوافق‪1433/7/22‬ه ـ الســاعة التاســعة صباحــا وعليــه حصــل‬\n     ‫التوقيــع ويف يــوم الثالثــاء املوافق‪1433/07/22‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال‬\n\n\n‫‪93‬‬\n\f‫مــن ميثلــه مــع تبلغــه لشــخصه مبوجــب ورقــة التبليــغ املرفقــة باملعاملــة‬\n‫وأحضــر املدعــي وكالــة معــه كال مــن ‪ ...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬و‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬وشــهد كل‬\n‫واحــد منهمــا قائــا أشــهد بــأن كل واحــد مــن الشــاهدين ‪...‬و‪ ...‬ثقــة‬\n‫وعــدل هكــذا شــهد كل واحــد منهمــا وقــد وردنــا قــرار هيئــة النظــر‬\n‫باحملكمــة رقــم ‪122‬ه ـ يف ‪1433/4/18‬ه ـ املتضمــن مــا نصــه أفيــد‬\n‫فضيلتكــم بــأن نفقــة الزوجــة املدعيــة مقدارهــا ســتمائة ريــال لــكل‬\n‫شــهر ومبلــغ أربعمائــة ريــال لــكل واحــد مــن األبنــاء ‪...‬و‪ ...‬و‪ ...‬أي مببلــغ‬\n‫إجمالــي ‪ 1800‬ريــال شــهريا هــذا مــا تضمنــه قــرار هيئــة النظــر ووقــع‬\n‫مــن أعضــاء هيئــة النظــر كل مــن ‪ ...‬و‪ ...‬و‪ ........‬ورئيــس هيئــة اخلبــراء‬\n‫‪ ......‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وكالــة ضــد املدعــى عليــه‬\n‫املتضمنــة طلبــه احلكــم علــى املدعــى عليــه بدفــع النفقــة املســتقبلية‬\n‫ملوكلتــه وأوالدهــا املذكوريــن مــن املدعــى عليــه الذيــن يقيمــون معهــا‬\n                                       ‫عنــد والدهــا منــذ تاريــخ ‪1430/8/1‬ه ـ‬\n‫وحلضــور املدعــى عليــه يف إحــدى اجللســات ومصادقتــه علــى أن املدعيــة‬\n‫زوجتــه وأنهــا أجنبــت األوالد املذكوريــن منــه وأنهــا حاليــا عنــد والدهــا‬\n‫ودفعه بأنها هي التي نشزت وخرجت إلى أهلها وأن األوالد املذكورين‬\n‫يف حضانتــه ال يف حضانتهــا ونظــرا إلــى أن األصــل عدم النشــوز ويؤكد‬\n‫ذلــك أن املدعــى عليــه لــم يذكــر أنــه طلــب انقيادهــا ولــم يــدع بذلــك‬\n‫ولــم يحضــر إلثبــات نشــوزها وكان غيــر ملتــزم بحضــور اجللســات يف‬\n‫مواعيدهــا ويثبــت ذلــك مــا جــاء يف محاضــر اجللســات الســابقة وألن‬\n‫املدعــي وكالــه أحضــر البينــة املعدلــة التــي شــهدت بــأن أوالد املدعــى‬\n‫عليــه املذكوريــن يقيمــون مــع أمهــم املدعيــة عنــد جدهــم ألمهــم يف ‪.....‬‬\n\n\n                                                                                      ‫‪94‬‬\n\f     ‫وهــم يف حضانتهــا منــذ حصــول املشــكلة بينهــا وبــن زوجهــا املدعــى‬\n     ‫عليــه يف شــهر ثمانيــة مــن عــام ‪1430‬ه ـ وحتــى اآلن ونظــرا إلــى أن‬\n     ‫احلضانــة تثبــت لــأم ولــو كانــت الزوجيــة قائمــة ويــدل علــى ذلــك مــا جاء‬\n     ‫يف اإلقنــاع وشــرحه كشــاف القنــاع مبــا نصــه ( فــإذا افتــرق الزوجــان‬\n     ‫ولهمــا طفــل أو معتــوه أو مجنــون ذكــر أو أنثــى فأحــق النــاس بحضانتــه‬\n     ‫أمــه كمــا قبــل الفــراق) انتهــى فقولــه كمــا قبــل الفــراق دليــل علــى‬\n     ‫أن لهــا احلــق يف احلضانــة قبــل الفــراق وألن األدلــة لــم تفــرق بــن حــال‬\n     ‫الفــراق وحــال الوئــام يف احلضانــة ولئــا حتصــل مضــارة لــأم بأوالدهــا‬\n     ‫ونظــرا إلــى أن النفقــة تســلم للحاضنــة فقــد جــاء يف املغنــي بشــأن نفقــة‬\n     ‫الولــد وتســليمها لــأم مــا نصــه (فأمــا إذا كان لــه منهــا ولــد فعليــه نفقــة‬\n     ‫ولــده ألنهــا واجبــة لــه فــا يســقط حقــه مبعصيتهــا كالكبيــر وعليــه أن‬\n     ‫يعطيهــا إياهــا إذا كانــت هــي احلاضنــة لــه أو املرضعــة) انتهــى مــن املغني‬\n     ‫وملــا تقــدم كلــه فقــد حكمــت علــى املدعــى عليــه الغائــب ‪ ...‬بــأن يســلم‬\n     ‫املدعيــة أصالــة النفقــة املســتقبلية لهــا وألوالدهــا املذكوريــن منــه كل‬\n     ‫شــهر ســتمائة ريــال للمدعيــة وأربعمائــة ريــال لالبــن ‪ ...‬وأربعمائــة ريــال‬\n     ‫لالبــن ‪ ......‬وأربعمائــة ريــال للبنــت ‪...‬وتســلم املبالــغ املذكــورة شــهريا‬\n     ‫ابتــداء مــن ‪1433/2/7‬ه ـ عــن طريــق اإليــداع يف حســاب املدعيــة يف‬\n     ‫أحــد البنــوك ويعــد هــذا احلكــم يف حــق املدعــى عليــه حضوريــا لتبلغــه‬\n     ‫لشــخصه وســوف يبلــغ باحلكــم حســب إجــراءات التبليــغ واختتمــت‬\n     ‫اجللســة الســاعة التاســعة والنصــف صباحــا وبــاهلل التوفيــق وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/07/22‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بعنيــزة‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n\n\n‫‪95‬‬\n\f‫بعنيــزة برقــم ‪ 3394242‬وتاريــخ ‪1433/2/7‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 33245592‬وتاريــخ ‪1433/2/7‬ه ـ وحضــر املدعــي وكالــة واملدعــى‬\n‫عليــه وقــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقصيــم‬\n‫وبرفقها القرار رقم ‪ 33430960‬يف ‪1433/10/18‬هـ املتضمن ما نصه‬\n‫بعــد املقدمــة (وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ اآلتــي أوال حكــم فضيلتــه بالنفقــة املســتقبلية‬\n‫ملوكلــة املدعــي مــع أن املدعــى عليــه دفــع بــأن زوجتــه موكلــة املدعــي‬\n‫ناشــز ولــم يتحقــق فضيلتــه مــن هــذا الدفــع ويســأل املدعــى عليــه هــل‬\n‫طالــب زوجتــه بعودتهــا إليــه ورفضــت ويطلــب حضــور املدعيــة أصالــة‬\n‫ويســألها عــن مــا ذكــره املدعــى عليــه وهــل ترغــب الذهــاب مــع زوجهــا‬\n‫إذا طلــب أم ال ســيما أن املدعــى عليــه ذكــر يف الئحتــه االعتراضيــة أن‬\n‫لديــه بينــة علــى نشــوز زوجتــه املذكــورة ثانيــا حكــم فضيلتــه بالنفقــة‬\n‫املســتقبلة ألوالده ـ منهــا علــى مــا قررتــه هيئــة النظــر والــذي باإلطــاع‬\n‫عليــه لــم جنــد معتمــده علــى هــذا التقديــر ولــم يتحقــق فيــه عــن مقــدار‬\n‫مرتبــه مــن قبــل مرجعــه ومالــه مــن دخــل آخــر إن وجــد ومــا عليــه مــن‬\n‫التزامــات أخــرى مــن النفقــة ملــن يعــول وأجــرة منــزل وغيرهــا إن وجــدت‬\n‫ليكــون التقديــر علــى قــدر ســعته لقولــه تعالــى( لينفــق ذو ســعت مــن‬\n‫ســعته) فعلــى فضيلتــه مالحظــة مــا ذكــر وإحلــاق مــا يجريــه بالضبــط‬\n‫والصــك وســجله ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل املوفــق) انتهــى‬\n‫قــرار االســتئناف وعليــه أجيــب أصحــاب الفضيلــة قضــاة االســتئناف‬\n‫عــن املالحظــة األولــى بأننــي ســألت املدعــى عليــه عــن زوجتــه فقــال إنهــا‬\n‫ناشــز وقــد طلبــت منهــا االنقيــاد وديــا وقــد قدمــت عليهــا دعــوى طلــب‬\n‫انقيــاد يف مقــر ســكنها يف محكمــة أبانــات والزالــت ولــدي بينــه علــى‬\n\n\n                                                                                     ‫‪96‬‬\n\f     ‫أنــي طلبتهــا إلــى بيــت الطاعــة مــن أول مــا خرجــت وذلــك يف شــهر شــوال‬\n     ‫مــن عــام ‪1430‬ه ـ وقــد ســألت املدعــي وكالــة هــل موكلتــه هــل هــي‬\n     ‫مســتعدة باالنقيــاد للمدعــى عليــه فقــال إنهــا غيــر مســتعدة باالنقيــاد‬\n     ‫إليــه وقــد ســألته عــن ذلــك فقالــت إنهــا قــد طابــت نفســها منــه هكــذا‬\n     ‫أجــاب املدعــي وكالــة وعــن املالحظــة الثانيــة فقــد ســألت املدعــى عليــه‬\n     ‫عــن راتبــه فقــال إن راتبــي تســعة آالف وأربــع مائــة ريــال هكــذا أجــاب‬\n     ‫املدعــى عليــه وقــد طلبــت مــن املدعــي إحضــار موكلتــه لســؤالها عــن‬\n     ‫رغبتهــا باالنقيــاد للمدعــى عليــه مــن عدمــه وهــل طلــب منهــا املدعــى‬\n     ‫عليــه االنقيــاد إليــه عندمــا خرجــت منــه مباشــرة أم ال ويف جلســة أخــرى‬\n     ‫حضــر املدعــي وكالــة واملدعــى عليــه وقــد ســألت املدعــي وكالــة عــن‬\n     ‫موكلتــه فقــال إنهــا ال ترغــب باحلضــور وإنهــا متنازلــة عــن دعواهــا‬\n     ‫بالنفقــة املدعــى بهــا لهــا وإمنــا تطالــب بنفقــة أوالدهــا املســتقبلية فقــط‬\n     ‫هكــذا قــرر املدعــي وكالــة ونظــرا إلــى أن إحضــار الزوجــة ســببه‬\n     ‫التحقــق مــن نشــوزها مــن عدمــه ومــا دامــت ال تطالــب بالنفقــة فــا أثــر‬\n     ‫حلضورهــا وعــن املالحظــة الثانيــة أجيــب بــأن النفقــة قــدرت مــن هيئــة‬\n     ‫النظــر وهــي نفقــة تعتبــر قليلــة بالنظــر إلــى راتــب املدعــى عليــه الــذي‬\n     ‫أقــر بــه وأمــا االلتزامــات فــإن النفقــة مقدمــة علــى االلتزامــات بنــاء علــى‬\n     ‫املــادة ‪ 7/217‬مــن لوائــح نظــام املرافعــات ونصهــا يجــوز احلجــز علــى‬\n                                               ‫مــال املديــن مــن راتـ ٍـب أو مخصصـ ٍ‬\n     ‫ـات بعــد تقديــر الكفايــة لــه مــن نفقــة‬\n     ‫ونحوهــا‪ .‬انتهــى وقــال يف كشــاف القنــاع (‪ ( )443/3‬وينفــق احلاكــم‬\n     ‫عليــه أي املفلــس وعلــى مــن تلزمــه نفقتــه مــن زوجــة وخــادم وقريــب ألنهــم‬\n     ‫يجــرون مجــرى نفســه مــن مالــه باملعــروف لقولــه ‪ -‬صلــى اهلل عليــه وســلم‬\n     ‫‪ -‬ابــدأ بنفســك ثــم مبــن تعــول‪ -‬وألن ملكــه بــاق عليــه قبــل القســمة‪).‬‬\n\n\n‫‪97‬‬\n\f‫انتهــى فبنــاء علــى مــا تقــدم كلــه وبنــاء علــى مــا قــرره املدعــي وكالــة‬\n‫مــن عــدم مطالبــة موكلتــه بالنفقــة املدعــى بهــا فقــد رجعــت عــن احلكــم‬\n‫بالنفقــة املســتقبلية املذكــورة للزوجــة املدعيــة أصالــة وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة قنــع بــه وأمــا حكمــي بالنفقــة لــأوالد فهــو علــى‬\n‫مــا هــو عليــه ولــم يظهــر لــي ما يوجب العــدول عنه وأمرت بإعــادة املعاملة‬\n‫حملكمــة االســتئناف إلكمــال الزمهــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/12/25‬هـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 3394242‬وتاريــخ ‪ 1433/02/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33245592‬وتاريــخ ‪ 1433/02/07‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/02/05‬ه ـ افتتحــت اجللســة وقــد عــادت إلينــا‬\n‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم ‪ 3491365‬يف‬\n‫‪1434/1/26‬ه ـ وبرفقهــا قــرار محكمــة االســتئناف بالقصيــم رقــم‬\n‫‪3415104‬يف ‪1434/1/18‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة « فــإن‬\n‫الدائــرة تقــرر مــا يلــي‪ :‬أوال‪ :‬املوافقــة علــى رجــوع فضيلتــه عمــا حكــم بــه‬\n‫مــن النفقــة املســتقبلية املذكــورة للمدعيــة أصالــة‪ .‬ثانيـاً‪ :‬املصادقــة علــى‬\n‫ماحكــم بــه مــن النفقــة لــأوالد املذكوريــن واهلل املوفــق» انتهــى‪ .‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                          ‫يف ‪1434/02/05‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 3394242‬وتاريــخ ‪ 1433/02/07‬ه ـ املقيــدة‬\n\n\n                                                                                       ‫‪98‬‬\n\f     ‫باحملكمــة برقــم ‪ 33245592‬وتاريــخ ‪1433/02/07‬ه ـ ففــي يــوم‬\n     ‫الســبت املوافــق ‪1434/3/14‬ه ـ افتتحــت اجللســة وقــد وردنــا خطــاب‬\n     ‫محكمــة االســتئناف بالقصيــم رقــم ‪ 34379350‬يف ‪1434/3/3‬ه ـ‬\n     ‫وبرفقــه قــرار محكمــة االســتئناف بالقصيــم رقــم ‪ 3447719‬يف‬\n     ‫‪1434/2/26‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة فلدينــا نحــن قضــاة‬\n     ‫الدائــرة املختصــة بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات يف‬\n     ‫محكمــة االســتئناف مبنطقــة القصيــم بنــاء علــى التمــاس إعــادة النظــر‬\n     ‫املقــدم لفضيلــة رئيــس احملكمــة باســم ‪ ...‬املقيــد لــدى احملكمــة برقــم‬\n     ‫‪ 34379350‬وتاريــخ ‪1434/2/16‬ه ـ احملــال إلينــا بشــرح فضيلتــه بتاريخ‬\n     ‫‪1434/2/13‬ه ـ املتعلــق بطلــب مقــدم االلتمــاس إعــادة النظــر يف احلكــم‬\n     ‫الصــادر بــه الصــك رقــم ‪ 33353081‬يف ‪1433/7/22‬ه ـ مــن فضيلــة‬\n     ‫الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبحافظــة عنيــزة اخلــاص بدعــوى‬\n     ‫‪ ...‬الوكيــل عــن ‪ ...‬ضــد ‪ ...‬بشــأن مطالبــة املدعيــة أصالــة بالنفقــة لهــا‬\n     ‫وألوالدهــا مــن املدعــى عليــه وهــم ‪...‬و‪ ...‬و‪ ...‬مــن املدعــى عليــه املتضمــن‬\n     ‫حكــم فضيلتــه بــأن يســلم املدعــى عليــه النفقــة املســتقبلة للمدعيــة‬\n     ‫أصالــة وألوالدهــا املكتســب الصفــة النهائيــة بتصديقــه مــن محكمــة‬\n     ‫االســتئناف بالقــرار رقــم ‪ 3415104‬وتاريــخ ‪1434/1/18‬ه ـ وباالطــاع‬\n     ‫علــى صحيفــة اإللتمــاس واألوراق املرفقــة املتضمــن أن ســبب طلــب‬\n     ‫االلتمــاس أنــه يطعــن بشــهود املدعيــة وأنــه ينفــق علــى أوالده وأن لديــه‬\n     ‫شــهودا علــى ذلــك وباإلطــاع علــى صــورة صــك احلكــم املرفقــة وصــورة‬\n     ‫ضبطــه احملفوظــة مبحكمــة االســتئناف وألن مــا ذكــره مــن ســبب‬\n     ‫طلــب االلتمــاس قــد مت النظــر فيــه أثنــاء نظــر الدعــوى وبعــد تقدميــه‬\n     ‫الالئحــة االعتراضيــة وذلــك مــن قبــل فضيلــة حاكــم القضيــة كمــا‬\n\n\n‫‪99‬‬\n\f‫أن احملكــوم بــه للنفقــة املســتقبلة وليســت للماضيــة حتــى يطلــب إعــادة‬\n‫النظــر فيــه وبنــاء علــى املــواد ‪ 192‬ـ ـ ‪ 193‬ـ ـ ‪ 3 / 195‬مــن نظــام املرافعــات‬\n‫الشــرعية فــإن الدائــرة تقــرر رفــض االلتمــاس وتزويــد فضيلــة حاكــم‬\n‫القضيــة بنســخة مــن قــرار رفــض االلتمــاس لتدوينــه يف الضبــط انتهــى‬\n‫وجــرى إحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة عنيــزة برقــم (‪ )331891418‬وتاريــخ ‪1434/1/7‬هــ؛‬\n‫املقيــدة لــدى احملكمــة برقــم (‪ )3491365‬وتاريــخ ‪1434/1/12‬هــ؛‬\n‫اخلاصــة بدعــوى ‪ ...‬الوكيــل عــن ‪...‬ضــد ‪...‬؛ بشــأن طلــب املدعيــة أصالــة‬\n‫النفقــة لهــا وألوالدهــا ‪ ..‬و‪ ...‬و‪ ...‬مــن املدعــى عليــه؛ املنتهيــة بالصــك‬\n‫الصــادر مــن فضيلــة الشــيخ‪ ...‬القاضــي باحملكمــة؛ املســجل برقــم‬\n‫(‪ )33353081‬وتاريــخ ‪1433/7/22‬هــ؛ املتضمــن حكــم فضيلتــه بــأن‬\n‫يســلم املدعــى عليــه النفقــة املســتقبلية للمدعيــة أصالــة وألوالدهــا ؛‬\n‫علــى النحــو املفصــل فيــه‪ .‬وقــد ســبق منــا دراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة‪ .‬وباالطــاع علــى مــا أجــاب فضيلتــه وأحلقــه بالصــك‬\n‫وصــورة ضبطــه جواب ـ ًا علــى قــرار الدائــرة رقــم(‪ )33430960‬وتاريــخ‬\n‫ـاء علــى مــا قــرره‬\n                   ‫‪1433/10/18‬ه ـ املتضمــن قــول فضيلتــه‪ ((:‬أنــه بنـ ً‬\n‫املدعــي وكالــة مــن عــدم مطالبــة موكلتــه بالنفقــة املدعــى بهــا وأمــا‬\n‫حكمــه بالنفقــة لــأوالد فهــو علــى ماهــو عليــه)) انتهــى فــإن الدائــرة‬\n‫تقــرر مــا يلــي‪ :‬أوالً‪ :‬املوافقــة علــى رجــوع فضيلتــه عمــا حكــم بــه مــن‬\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫النفقــة املســتقبلية املذكــورة للمدعيــة أصالــة‪ .‬ثاني ـاً‪ :‬املصادقــة علــى‬\n      ‫ماحكــم بــه مــن النفقــة لــأوالد املذكوريــن‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪101‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":88,"source_page_end":101,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44a252f3d1e397ed2e40d71179fbe16fbb70dec612ed2ed73b2089874d9281cb","normalized_text_hash":"2a39d25049580787ba318d14864f8103a32133762f82dbf9c1d048cbf6e4c22d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p88-33353081"},{"id":"3893fff3-62ec-5557-a78d-bef17ca2d06c","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة ابنها املستقبلية -تقدير نفقة من قبل قسم اخلبراء -عدم األخذ بتقدير أهل اخلبرة ملوجب -احلكم","document_number":"34259122","case_number":"33377222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/4","year":"1434","subject":"نفقة -مطالبة أم بنفقة ابنها املستقبلية -تقدير نفقة من قبل قسم اخلبراء -عدم األخذ بتقدير أهل اخلبرة ملوجب -احلكم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/7/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34259122 :‬‬\n                   ‫َر ْق ُم الدعوى‪33377222 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34307514‬تاريخه‪1434/2/28 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة أم بنفقــة ابنهــا املســتقبلية ‪ -‬تقديــر نفقــة مــن قبــل‬\n‫قســم اخلبــراء ‪ -‬عــدم األخــذ بتقديــر أهــل اخلبــرة ملوجــب ‪ -‬احلكــم‬\n                                                                ‫بالنفقــة‪.‬‬\n\n\n\n\n                                         ‫قوله تعالى {ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِتهِ}‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بــأن املدعــى عليــه كان‬\n‫زوجـ ًا ملوكلتــه وقــد ولــدت لــه علــى فــراش الزوجيــة ولــد ًا واحــد ًا بتاريــخ‬\n‫‪1430/7/16‬ه ـ وإن ابنهــا مقيــم مــع والدتــه وطلــب املدعــي وكالــة‬\n‫تقديــر نفقــة مســتقبلية شــهرية مــن ‪1434/2/1‬ه ـ البــن موكلتــه قدرهــا‬\n‫ألــف ريــال‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أنــه ال‬\n‫يوافــق علــى املطالبــة بألــف ريــال شــهري ًا وإن املناســب خمســمائة ريــال‪،‬‬\n‫مت تقديــر النفقــة مــن قبــل قســم اخلبــراء باحملكمــة بألــف وثالثمائــة‬\n‫ريــال شــهرياً‪ ،‬قــرر املدعــي وكالــة قناعتــه بالتقديــر وقــرر املدعــى‬\n‫عليــه عــدم قناعتــه‪ ،‬أطلــع ناظــر القضيــة علــى إلتزامــات املدعــى عليــه‬\n‫الشــهرية‪ ،‬قــرر ناظــر القضيــة إنــه نظــر ًا حلاجــة االبــن للنفقــة ال ســيما إذا‬\n‫كان صغيــر ًا وألن تقديــر قســم اخلبــراء مبالــغ فيــه والنفقــة ينظــر فيهــا‬\n\n                                                                                                    ‫‪102‬‬\n\f      ‫حلــال املنفــق وألن املدعــي وكالــة طالــب يف البدايــة بألــف ريــال وهــذا‬\n      ‫يــدل بأنهــا كافيــه ولألســباب املرصــودة ولقولــه تعالــى {ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة‬\n      ‫مِ ــنْ َسـ َـع ِتهِ} فقــد صــدر احلكــم علــى املدعــى عليــه بــأن يســلم للمدعيــة‬\n      ‫أصالــة ألــف ريــال شــهري ًا نفقــة لالبــن‪ ،‬قــرر املدعــى عليــه القناعــة‬\n      ‫وقــرر املدعــي وكالــة عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                                   ‫مبكــة املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪ 33377222‬وتاريــخ‬\n      ‫‪1433/06/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331041187‬وتاريــخ‬\n      ‫‪1433/06/03‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/01/27‬ه ـ‬\n      ‫حضــر‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .....‬الوكيــل‬\n      ‫عــن مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة‬\n      ‫رقــم ‪.........‬يف ‪1433/3/22‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n      ‫واالقــرار والصلــح واالنــكار والتنــازل وحضــر حلضــوره ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .....‬وادعــى األول قائــا ان هــذا‬\n      ‫احلاضــر كان زوج ملوكلتــي وقــد ولــدت لــه علــى فــراش الزوجيــة ولــدا‬\n      ‫واحــدا اســمه ‪ .....‬املولــود يف تاريــخ ‪1430/7/16‬ه ـ وابنهــا يقيــم عندهــا‬\n      ‫اآلن أطلــب حتديــد نفقــة مســتقبلية شــهرية مــن تاريــخ ‪1434/2/1‬ه ـ‬\n      ‫البــن موكلتــي وقدرهــا الــف ريــال هكــذا ادعــى وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه اجــاب قائــا مــا ذكــره املدعــي كلــه صحيــح وال مانــع‬\n\n‫‪103‬‬\n\f‫لــدي مــن حتديــد نفقــة مســتقبلية البنــي ‪ .........‬امــا مــا طلبــه املدعــي‬\n‫وكالــة بــان تكــون النفقــة الشــهرية ألــف ريــال فانــا غيــر موافــق عليهــا‬\n‫والقــدر املناســب هــو خمســمائة ريــال ومســتعد بتســليمها هكــذا‬\n‫أجــاب ونظــرا لوصــول القضيــة لهــذا احلــد فقــد امــرت بالكتابــة لقســم‬\n‫اخلبــراء باحملكمــة لتحديــد النفقــة املســتقبلية البــن املتداعيــن‪ .‬ويف يــوم‬\n‫الثالثــاء املوافــق‪1434/07/04 :‬ه ـ حضــر املدعــي وكالــة‪ ، :‬واملدعــى‬\n‫عليــه أصالــة‪ ، :‬املثبــت حضورهمــا يف جلســة ســابقة‪ ،‬وكنــا قــد كتبنــا‬\n‫لقســم اخلبــراء باحملكمــة لتقديــر نفقة ابن طــريف النزاع (‪ ).....‬ولم تردنا‬\n‫اإلفــادة حتــى اآلن‪ ،‬وقــرر طــريف النــزاع قائلــن‪ :‬إننــا اجتمعنــا مــع اخلبــراء‬\n‫باحملكمــة وقــدروا أن النفقــة الشــهرية تكــون ألــف وثالثمائــة ريــال‬\n‫شــهريا‪ ،‬هكــذا قــرر‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائــا‪:‬‬\n‫تقديــر مناســب‪ ،‬وأطلــب إلزامــه بتســليم هــذا املبلــغ شــهريا ملوكلتــي‬\n‫هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أصالــة أجــاب قائــا‪:‬‬\n‫تقديــر مبالــغ فيــه جــدا‪ ،‬وأنــا مســتعد بتســليم ســتمائة ريــال اعتبــارا‬\n‫مــن تاريــخ‪1434/2/1 :‬ه ـ وأمــا أكثــر مــن ذلــك فــا‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبســؤاله عــن مرتبــه الشــهري أجــاب قائــا‪ :‬مبلغــا قــدره‪ :‬ســتة وعشــرون‬\n‫ألــف ريــال‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله عــن دخــل آخــر لــه أجــاب قائــا‪:‬‬\n‫لــدي شــقتني إيجارهمــا الســنوي مبلغــا قــدره‪ :‬واحــد وأربعــون ألف ريال‪،‬‬\n‫هكــذا أجــاب‪ .‬وبســؤاله عــن عــدد األفــراد الــذي ينفــق عليهــم أجــاب‬\n‫قائــا‪ :‬بيتــي ملــك‪ ،‬وعنــدي زوجــة وســبعة أوالد‪ ،‬وأم وخادمــة وســائق‪،‬‬\n‫كلهــم أنفــق عليهــم‪ ،‬وأقســاط شــهرية للبنــك العقــاري كل شــهر ألــف‬\n‫وثمامنائــة ريــال‪ ،‬وأقســاط العمــارة التــي أســكنها أســدد البنــك كل‬\n‫شــهر تســعة آالف وخمســمائة ريــال‪ ،‬يبقــى مــن مرتبــي الشــهري مبلغــا‬\n\n\n                                                                                        ‫‪104‬‬\n\f      ‫قــدره‪ :‬أربعــة عشــر ألفــا وســبعمائة ريــال‪ ،‬هكــذا أجــاب‪ .‬وبعــرض ذلــك‬\n      ‫علــى املدعــي وكالــة أجــاب قائــا‪ :‬مــا ذكــره غيــر صحيــح‪ ،‬وســوف‬\n      ‫تتــزوج إحــدى بناتــه يف هــذا الصيــف وتســقط نفقتهــا‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه أجــاب قائــا‪ :‬ليــس لــدي بينــة‪ ،‬هكــذا أجــاب‪ .‬فبنــاء‬\n      ‫علــى مــا ســلف‪ ،‬وحلاجــة الولــد للنفقــة ـ ال ســيما إذا كان صغيــر ًا ـ ‪،‬‬\n      ‫وألن الوالــد جتــب عليــه نفقــة ولــده كاملــة ينفــرد بهــا‪ ،‬وألن تقديــر‬\n      ‫قســم اخلبــراء مبالــغ فيــه‪ ،‬وألن صــايف دخــل املدعــى عليــه الشــهري‬\n      ‫ثمانيــة عشــر ألــف ريــال تقريبــا‪ ،‬وألن النفقــة ينظــر فيهــا حلــال املنفــق‬\n      ‫لقــول اهلل ـ تعالــى ـ‪( :‬لينفــق ذو ســعة مــن ســعته)‪ ،‬وألن املدعــي وكالــة‬\n      ‫طالــب يف دعــواه ابتــداء بألــف ريــال وهــذا يــدل علــى أنهــا كافيــة‬\n      ‫لــه‪ ،‬لذلــك كلــه فقــد قــررت أن نفقــة ابــن املدعــى عليــه (‪ ).....‬ألــف‬\n      ‫ريــال شــهريا اعتبــارا مــن تاريــخ‪1434/2/1 :‬ه ـ وأمــرت املدعــى عليــه‬\n      ‫بتســليمها لوالــدة الطفــل املدعيــة‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم‬\n      ‫قــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬أمــا املدعــي وكالــة فقــرر عــدم‬\n      ‫اعتراضيــة‪ ،‬فأفهمتــه بــأن لــه احلــق يف‬\n                                           ‫ّ‬             ‫ـتعد بتقــدمي الئحــة‬\n                                                                          ‫القناعــة واسـ ّ‬\n      ‫تقــدمي اعتراضــه خــال ثالثــن يومـ ًا اعتبــار ًا مــن هــذا اليــوم‪ ،‬وإذا انتهــت‬\n      ‫حقــه يف االعتــراض واكتســب‬       ‫املـ ّـدة احملــددة ولــم يقــدم الئحتــه ســقط ّ‬\n      ‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                           ‫ّ‬     ‫احلكــم‬\n                                   ‫آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/07/04 :‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم اإلثنــن املوافــق‪1434/09/14 :‬ه ـ‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار دائــرة األحــوال‬\n      ‫الشــخصية الثانيــة رقــم‪ 34307514 :‬يف‪1434/08/28 :‬ه ـ ونص احلاجة‬\n      ‫منــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n\n\n‫‪105‬‬\n\f‫املوافقــة علــى احلكــم)‪ .‬أ‪ .‬ه ـ وللبيــان جــرى إثباتــه‪ ،‬وأمــرت بإحلــاق ذلــك‬\n‫علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/09/14 :‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا‬\n‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ ‪.........‬القاضــي‬\n‫باحملكمــة العامــة بجــدة برقم ‪ 34259122‬وتاريخ ‪1434/7/4‬هـ بشــأن‬\n‫دعــوى‪ .........‬ضــد‪ ،.........‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم مــع مالحظــة التنبيــه املرفــق‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪106‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":102,"source_page_end":106,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b2112d707a974a6a64555266d27bcc41fd428cafb5b0c594386c703d7ec49cc7","normalized_text_hash":"8a970b31f924d8819db56265d7b91a4fab2e0402da0a86d15e6dbcbf47d238d0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p102-34259122"},{"id":"94f72465-da0e-5f27-aa30-e3afbeb20268","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة أوالد -املطالبة بالنفقة املاضية -األخذ بقول األوالد فيمن أنفق عليهم حال اخلاف بن الزوجن -مين االستظهار يف النفقة عن نية الرجوع -احلكم بالنفقة .","document_number":"33395847","case_number":"3257493","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/27","year":"1434","subject":"نفقة -نفقة أوالد -املطالبة بالنفقة املاضية -األخذ بقول األوالد فيمن أنفق عليهم حال اخلاف بن الزوجن -مين االستظهار يف النفقة عن نية الرجوع -احلكم بالنفقة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/8/27 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33395847 :‬‬\n                          ‫َر ْق ُم الدعوى‪3257493 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34261408‬تاريخه‪1434/1/20 :‬هـ‬\n\n\n\n      ‫نفقــة‪ -‬نفقــة أوالد‪ -‬املطالبــة بالنفقــة املاضيــة‪ -‬األخــذ بقــول األوالد‬\n      ‫فيمــن أنفــق عليهــم حــال اخلــاف بــن الزوجــن‪ -‬ميــن االســتظهار يف‬\n                               ‫النفقــة عــن نيــة الرجــوع‪ -‬احلكــم بالنفقــة ‪.‬‬\n\n\n\n\n                                     ‫‪ -1‬قوله تعالى ( لينفق ذو سعه من سعته)‬\n         ‫‪ -2‬قوله صلى اهلل عليه وسلم ( كفى باملرء إثم ًا أن يضيع من يعول)‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم لهنــد بنــت عتبــه ( خــذي مــن مالــه‬\n                                  ‫باملعــروف مــا يكفيــك ويكفــي بنيــك)‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة با ُنهــا كانــت زوجــة للمدعــى عليــه وطلقهــا وانتقلــت إلــى‬\n      ‫أهلهــا وتركــت أوالدهــا الســبعة عنــد والدهــم املدعــى عليــه‪ ،‬أخــذت‬\n      ‫أوالدهــا عــن طريــق الشــرطة بعــد أن جلــأوا ملنــزل جارهــم علــى أثر خالف‬\n      ‫مــع أبيهــم املدعــى عليــه وإســاءة معاملتهــم‪ ،‬وطلبت املدعيــة إلزام املدعى‬\n      ‫عليه بتســليم نفقة أوالدها الســبعة من بداية شــهر رمضان عام ‪1431‬هـ‬\n      ‫حتــى تاريخــه‪ ،‬وصــادق املدعــى عليــه علــى دعــوى املدعيــة وذكــر بــأن‬\n      ‫أوالده الســبعة خرجــوا مــن بيتــه بتحريــض مــن أمهــم املدعيــة وأخــذت‬\n      ‫األوالد عــن طريــق الشــرطة علــى أن يبقــوا عندهــا يــوم أو يومــن وأنهــا‬\n\n‫‪107‬‬\n\f‫تعهــدت شــفهي ًا بإعادتهــم ولــم تعدهــم حتــى حكــم لــه أخيــر ًا بإعــادة‬\n‫األوالد‪ ،‬وقــد دفــع املدعــى عليــه بــأن املدعيــة ال تســتحق مــا طلبتــه ألنهــا‬\n‫أخــذت أوالده الســبعة عنــوة وأن أربعــة منهــم وهــم الصغــار يتــرددون بينــه‬\n‫وبينهــا وأنــه ينفــق عليهــم وأن البنــات الثــاث الكبــار يدرســن باجلامعــة‬\n‫ولهــن مكافئــات‪ ،‬واملدعيــة تأخــذ مــن الضمــان عــن األوالد الســبعة‬\n‫بــدون علمــه‪ ،‬وقــد أنكــرت املدعيــة هــذا الدفــع‪ ،‬ثــم جــرى تقديــر نفقــة‬\n‫األوالد املاضيــة مــن قبــل هيئــة النظــر‪ ،‬حيــث أن النفقــة الشــرعية علــى‬\n‫األوالد متعينــة يف األصــل علــى أبيهــم و لقولــه تعالــى (لينفــق ذو ســعة‬\n‫مــن ســعته) ولقــول النبــي صلــى اهلل عليــة وســلم (كفــى باملــرء إثمــا أن‬\n‫يضيــع مــن يعولــه) ولقولــه صلــى اهلل عليــة وســلم لهنــد بنــت عتبــه (خــذي‬\n‫مــن مالــه مــا يكفيــك ويكفــي بنيــك)‪ ،‬لــذا صــدر احلكــم علــى املدعــى‬\n‫عليــه بــأن يســلم للمدعيــة مائــه وثمانيــة وســتني ألــف ريــال نفقــة ســنتني‬\n‫ألوالدهمــا‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم‪ ،‬كمــا لوحــظ علــى‬\n‫احلكــم مــن محكمــة االســتئناف‪ ،‬وقــد حضــر أربعــة أوالد وقــرروا أنهم‬\n‫مكثــوا عنــد والدهــم ثالثــة أشــهر وكان ينفــق عليهــم فيهــا‪ ،‬وحلفــت‬\n‫املدعيــة ميــن االســتظهار علــى أنهــا كانــت تنــوي الرجــوع علــى املدعــى‬\n‫عليــه فيمــا أنفقتــه‪ ،‬وعليــه رجــع القاضــي عــن حكمــة الســابق وحكــم‬\n‫علــى املدعــى عليــه بــأن يدفــع للمدعيــة مائــة وســته وخمســن ألــف ريــال‬\n‫بعــد خصــم نفقــة األوالد األربعــة ملــدة ثالثــة أشــهر‪ ،‬واعترضــت املدعيــة‬\n                 ‫علــى احلكــم‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                       ‫‪108‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالدمــام برقــم ‪ 3257493‬وتاريــخ ‪ 1432/02/27‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32178712‬وتاريــخ ‪ 1432/02/27‬ه ـ ففــي يــوم‬\n      ‫اإلثنــن املوافــق‪ 1433/03/21‬ه ـ حضــرت ‪...‬بالبطاقــة رقــم ‪...‬وحضــر‬\n      ‫حلضورهــا املدعــى عليــه ‪...‬بالبطاقــة رقــم ‪...‬وفيهــا قالــت ‪...‬لقــد كنــت‬\n      ‫زوجــة للمدعــى عليــه وطلقنــي منــذ تاريــخ ‪1430/12/1‬ه ـ فانتقلــت الــى‬\n      ‫أســرتي يف دولــة األمــارات العربيــة املتحــدة وتركت أوالدي الســبعة وهم‬\n      ‫‪ ......‬و‪ ...‬و‪...‬و‪ ...‬و‪ ...‬و‪ ......‬و‪...‬أوالد املدعى عليه ‪...‬عنده ويف كفالته وقد‬\n      ‫ذكــر لــي والــدي يف شــهر رجــب مــن عــام ‪1431‬ه ـ أن املدعــى عليــه ابلغه‬\n      ‫أن أوالدي خرجــوا مــن منزلــه الكائــن يف حــي ‪ ..........‬بالدمــام وأنــه‬\n      ‫ال يعــرف مكانهــم فحاولــت التحــري فتبــن لــي أنــه أســاء معاملتهــم‬\n      ‫ويرغــب يف تزويــج احــدى البنــات دون رضاهــا وأنهــم هربــوا مــن منزلــه‬\n      ‫وقــد ابلغــت الســلطات األمنيــة املختصــة واضطــررت إلــى احلضــور إلــى‬\n      ‫الدمــام فوجدتهــم يف حــوش منــزل اجليــران حيــث حضــرت مــع الضابــط‬\n      ‫‪...‬مــن شــرطة اجلنوبيــة بالدمــام ومعنــا بعــض األفــراد فأخرجناهــم‬\n      ‫مــن حــوش منــزل اجلــار الــذي كانــوا يلجئــون عنــده فأخذتهــم وقمــت‬\n      ‫باإلنفــاق عليهــم بجميــع مــا يحتاجونــه مــن مــأكل ومشــرب وعــاج‬\n      ‫وتعليــم ومواصــات ولــذا أطلــب الزامــه بتســليم نفقتهــم مــن بدايــة شــهر‬\n      ‫رمضــان مــن عــام ‪1431‬ه ـ حتــى اليــوم هذه دعــواي وبســؤال املدعى عليه‬\n      ‫عــن هــذه الدعــوى قــال مــا ذكرتــه املدعيــة مــن انهــا كانــت زوجــة لــي‬\n\n‫‪109‬‬\n\f‫ثــم طلقتهــا بعــد ان اجنبــت االوالد املذكوريــن وانهــا انتقلــت إلــى أهلهــا‬\n‫يف (اإلمــارات) فصحيــح وقــد خــرج أوالدي الســبعة مــن منزلــي املذكــور‬\n‫يف شــهر رجــب مــن عــام ‪1431‬ه ـ بتحريــض منهــا ثــم حضــرت إلــى الدمام‬\n‫وأبلغــت الســلطات وشوشــت عليهــم فحضرت مع رجــال األمن إلى حوش‬\n‫منزلــي املؤجــر وأخــذوا أوالدي وســلموهم لهــا واســتأذنوني يف ان يبقــوا‬\n‫عندهــا يــوم او يومــن فوافقــت فأبقتهــم عندهــا مــع انهــا تعهــدت شــفهي ًا‬\n‫بإعادتهــم حتــى حكــم لــي أخيــر ًا عليهــا بإعــادة األوالد مبوجــب الصــك‬\n‫الصــادر مــن هــذه احملكمــة يف شــهر صفــر مــن هــذا العــام مــع العلــم‬\n‫أنــي حاولــت أخــذ اوالدي قبــل هــذا احلكــم فرفضــوا وذكــروا أن لديهم‬\n‫دعــوى يف احملكمــة وقــد انتهــت تلــك الدعــوى ولــم ينفــذ احلكــم ألنــه لم‬\n‫يكتســب القطعيــة وقــد أرســلت وســطاء للمدعيــة وذكرت اني مســتعد‬\n‫بجميــع مــا يحتاجــه اوالدي مــن نفقــة حتــى يحكــم يف القضيــة فردتهــم‬\n‫ولــم تقبــل منهــم ومــع ذلــك كنــت أصــرف علــى اوالدي األربعــة الصغــار‬\n‫دون ان تعلــم املدعيــة شــيئ ًا مــن ذلــك وال أوافــق علــى تســليم املدعيــة‬\n‫شــيئ ًا ممــا تطالــب بــه ألنهــا أخذتهــم عنــوة علمـ ًا أن يف ذمتهــا لــي أكثــر‬\n‫مــن مائــة وخمســن ألــف ولــم أطالــب بهــا فــإن أصــرت علــى طلبهــا وتبــن‬\n‫لهــا حــق فعليهــا حســمه مــن املبلــغ الــذي عندهــا لــي هــذه اجابتــي ثــم يف‬\n‫جلســه أخــرى حضــر الطرفــان فجــرى عــرض الصلــح بينهمــا فيمــا يتعلــق‬\n‫بنفقــة األوالد التــي تطالــب بهــا املدعيــة فأصــرت املدعيــة علــى املطالبــة‬\n‫بنفقــة ســنتني مــن بدايــة شــهر رمضــان مــن عــام ‪1431‬ه ـ إلــى نهايــة شــهر‬\n‫شــعبان ‪1433‬ه ـ وذكــرت أنهــا انفقــت مــن مالهــا علــى أوالدهــا بنيــة‬\n‫الرجــوع علــى والدهــم وانهــا اســتدانت يف ســبيل ذلــك ثــم قالــت إن هيئــة‬\n‫النظــر باحملكمــة قــدرت النفقــة الشــهرية لــأوالد الســبعة ســبعة آالف‬\n\n\n                                                                                        ‫‪110‬‬\n\f      ‫ريــال وأنــا قانعــه بهــذا التقديــر ولــذا فإنــي أطالــب مبائــه وثمانيــة وســتني‬\n      ‫ألــف ريــال (‪ )168.000‬هــي نفقــة أربعه وعشــرين شــهرا أما املدعى عليه‬\n      ‫فقــال لقــد أخــذت أوالدي الســبعة عنــوة وأن أربعــه منهــم وهــم الصغــار‬\n      ‫يتــرددون بينــي وبينهــا وأنــا أنفــق عليهــم أمــا البنــات الثــاث الكبــار‬\n      ‫فيدرســن يف اجلامعــة ولهــن مكافــآت واملدعيــة تأخــذ مــن الضمــان عــن‬\n      ‫األوالد الســبعة وذلــك بــدون علمــي ولذلــك لــم تنفــق هــذا املبلــغ التــي‬\n      ‫تطالــب بــه وأمــا تقديــر هيئــة النظــر النفقــة الشــهرية لــأوالد الســبعة‬\n      ‫بســبعة آالف ريــال فهــذا أمــر مت يف غيبتــي وال أوافــق عليــه هكــذا قــرر‪.‬‬\n      ‫وبــرد ذلــك علــى املدعيــة قالــت مــا ذكــره املدعــى عليــه مــن أنــي اســتلم‬\n      ‫مــن الضمــان االجتماعــي ضمانــا لــأوالد غيــر صحيــح وأنــا موظفــه وال‬\n      ‫اســتحق أي ضمــان كمــا أن بناتــي الكبــار يدرســن يف كليــة املجتمــع‬\n      ‫وهــي كليــه ال تصــرف مكافــآت ملــن كان يف الدبلــوم وإحــدى البنــات‬\n      ‫تــدرس قســم تســويق عــن بعــد واســلم رســوم للكليــة عنهــا تبلــغ ثالثــة‬\n      ‫آالف وســبعمائة ريــال عــن الفصــل األول واملدعــى عليــه موظــف يف‬\n      ‫شــركة ‪ .......‬يصــل راتبــه الشــهري إلــى أربعــن ألــف ريــال كمــا انــه‬\n      ‫يؤجــر الــدور األرضــي والــذي كان ســكنا ألوالدي بخمســن ألــف ريال‬\n      ‫كمــا يســتلم املدعــى عليــه رواتــب عيديــه مــن شــركة ‪ .......‬بــل يســتلم‬\n      ‫خمســة عشــر راتبــا يف الســنه وهــو علــى وجــه تقاعــد ولــه مســتحقات‬\n      ‫نهايــة اخلدمــة تصــل إلــى ثالثــة ماليــن ريــال ( ‪ ) 3.000.000‬ولذلــك‬\n      ‫عليــه أن يقــوم بواجباتــه هــذه افادتــي ثــم قــال املدعــى عليــه ان لــي ســنتني‬\n      ‫وأنــا أطالــب بإعــادة أوالدي الســبعة فهــم اخــذوا بقــوة الســلطة املبنيــة‬\n      ‫علــى ادعــاءات كاذبــة ولذلــك غيــر معقــول أن الــزم بنفقــة الســنتني التــي‬\n      ‫تطالــب بهــا املدعيــة فمنــذ أخــذت املدعيــة أوالدي يف شــهر شــعبان مــن‬\n\n\n‫‪111‬‬\n\f‫عــام ‪1431‬ه ـ وحتــى اليــوم وأنــا أطالــب بإعادتهــم ولذلــك ال يصــح أن‬\n‫تخــرج املدعيــه أوالدي مــن بيتــي اململــوك لــي وتســتأجر لهــم ثــم أغــرم‬\n‫بدفــع األجــرة وأطلــب التأكــد مــن قبــل احملكمــة ان كانــت املدعيــة‬\n‫تســتلم أي ضمــان أو مكافــأه عــن األوالد هــذا جميــع مــا لــدي وكان‬\n‫قــد كتــب لهيئــة النظــر باحملكمــة لتقديــر نفقــة األوالد الســبعة فوردنــا‬\n‫قرارهــم رقــم ‪ 203‬يف ‪1432/06/19‬ه ـ ونصــه ( احلمــد هلل وحــده وبعــد‬\n‫بنــاء علــى أمــر فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة بالدمــام‬\n‫بشــأن حتديــد نفقــة شــهرية ألوالد املدعيــة ‪...‬مــن والدهــم املدعــو ‪/‬‬\n‫‪ ....‬هــذا ونظــرا إلــى أن حتديــد النفقــة يتطلــب معرفــة مســتوى دخــل‬\n‫املدعــى عليــه ومبــا أن ‪...‬املذكــور يعمــل لــدى شــركة ‪ .........‬فقــد جــرت‬\n‫الكتابــة ملديــر شــئون ‪ .......‬لإلفــادة عــن مســتوى دخلــه فــورد اجلــواب‬\n‫املرفــق مفــاده أن راتــب ‪...‬األساســي هــو مبلــغ ( ‪ ) 20.190‬عشــرين ألــف‬\n‫ومائــة وتســعني ريــال كمــا أنــه يحصــل علــى بــدالت ومكافئــات ثابتــه‬\n‫حســبما أوضحهــا خطــاب شــئون ‪ ........‬املرفــق هــذا وحيــث أن عــدد‬\n‫األوالد ســبعة خمــس بنــات وولديــن ومبــا أن دخــل والدهــم مســتواه جيــد‬\n‫حســبما أوضحــه خطــاب جهــة عملــه تــرى هيئــة النظــر أن تكــون نفقــة‬\n‫كل واحــد منهــم ( ‪ ) 1000‬ألــف ريــال لــكل شــهر مبعــدل ( ‪7000‬‬\n‫) ســبعة آالف ريــال شــهريا شــاملة للنفقــه والكســوة والســكنى هــذا‬\n‫مــا تقــرر وبــاهلل التوفيــق ) كمــا وجــد يف لفــات املعاملــة خطــاب مديــر‬\n‫شــؤون ‪ ......‬ويحمــل الرقــم ( ‪ ) 2011-4970-6‬ونــص احلاجــة منــه مــا يلي‬\n‫( أفيــد فضيلتكــم بــأن دخــل املوظــف املذكــور الثابــت هــو كالتالــي ‪:‬‬\n‫( ‪ ) 20.190‬رياال ســعوديا يف الشــهر كراتب أساســي ‪ .‬ثالثة رواتب يف‬\n‫الســنه بــدل ســكن ‪ .‬راتــب شــهرين يف الســنه مكافــأة ‪ ) 3028 ( .‬ريــاال‬\n\n\n                                                                                   ‫‪112‬‬\n\f      ‫ســعوديا يف الشــهر بــدل ‪ ) 2019 ( . .......‬ريــاال ســعوديا يف الشــهر عــاوة‬\n      ‫نوبــة ‪ ) 450 ( .‬ريــاال ســعوديا يف الشــهر بــدل انتقــال ) وبعــرض ذلــك‬\n      ‫علــى الطرفــن قالــت املدعيــة أنــا قانعــه بهــذا التقديــر أمــا املدعــى عليــه‬\n      ‫فقــال البــدالت املشــار إليهــا تكــون يف أوقــات دون أوقــات هكــذا قــرر‬\n      ‫الطرفــان فكــررت عــرض الصلــح بــن الطرفني مرة أخــرى فأصر كل‬\n      ‫منهمــا علــى رأيــه املدعيــة تطالــب بالنفقــة كاملــه ملــدة ســنتني واملدعــى‬\n      ‫عليــه يرفــض أن يســلم شــيئا ثــم أضــاف لقــد تســببت املدعية لــي بأضرار‬\n      ‫يف عملــي حيــث تدلــي ضــدي بإدعــاءات كاذبــه ولــدي أدلــة علــى ذلــك‬\n      ‫كمــا أنــي ســبق أن ســلمت للمدعيــة مائــة ألــف ريــال عندمــا كانــت يف‬\n      ‫ذمتــي وســبب ذلــك أنــي تزوجــت عليهــا فغضبــت فأرضيتهــا بهــذا املبلــغ‬\n      ‫لتبقــى يف البيــت مــع أوالدهــا لكنهــا أخــذت املبلــغ ودمــرت منزلــي حتــى‬\n      ‫طلــب أهلهــا أن أطلقهــا فطلقتهــا كفــا للشــر بــل إن والدهــا هــو الــذي‬\n      ‫طلــب منــي طالقهــا هــذا جميــع مــا لــدي وبتأمــل مــا ســبق ضبطــه تبــن‬\n      ‫أن أوالد الطرفــن الســبعة انتقلــوا إلــى والدتهــم املدعيــة بســبب خــاف‬\n      ‫بــن املدعــى عليــه وبينهــم وال يزالــون عندهــا مــع صــدور حكــم ضدهــا‬\n      ‫بتسليمهم للمدعى عليه مبوجب الصك الصادر منا برقم ( ‪)3381658‬‬\n      ‫يف ‪1433/02/14‬هـ وألن ذلك احلكم لم يكتســب القطعية إال أخيرا‬\n      ‫مبوجــب قــرار محكمــة االســتئناف باملنطقــة الشــرقية بالقــرار رقــم‬\n      ‫(‪ )33365388‬يف ‪1433/08/04‬ه ـ ولــم تبلــغ بــه املدعيــة إال يف هــذه‬\n      ‫اجللســة ممــا يجعــل املــدة التــي بقــي فيهــا األوالد لديهــا تبلــغ ســنتني وفقــا‬\n      ‫ملــا أقــر بــه الطرفــان وألن هيئــة النظــر قــدرت النفقــة الشــهرية لــأوالد‬\n      ‫بســبعة آالف ريــال بنــاء علــى دخــل املدعــى عليــه وبــذا تكــون النفقــة‬\n      ‫ملــدة ســنتني مائــه وثمانيــه وســتون ألــف ريــال ( ‪ ) 168.000‬وألن النفقــه‬\n\n\n‫‪113‬‬\n\f‫الشــرعية علــى األوالد متعينــه يف األصــل علــى أبيهــم ولقــول اهلل تعالــى (‬\n‫لينفــق ذو ســعه مــن ســعته ) ولقــول النبــي صلــى اهلل عليــه وســلم ( كفــى‬\n‫باملــرأ اثمــا ان يضيــع مــن يعــول ) ولقولــه صلــى اهلل عليــه وســلم لهنــد بنت‬\n‫عتبــة ( خــذي مــن مالــه باملعــروف مــا يكفيــك ويكفــي بنيــك ) لــكل‬\n‫ذلــك حكمــت علــى املدعــى عليــه ‪...‬أن يســلم للمدعيــه مائــه وثمانيــه‬\n‫وســتني ألــف ريــال ومتثــل نفقــة ســنتني ألوالدهمــا وبعــرض احلكــم علــى‬\n‫الطرفــن قنعــت بــه املدعيــة واعتــرض عليــه املدعــى عليــه فأفهمتــه بــأن‬\n‫لــه احلضــور يــوم اإلثنــن ‪1433/08/26‬ه ـ إلســتالم صــورة مــن احلكــم‬\n‫لتقــدمي اعتراضــه عليــه كمــا أفهــم بــأن مــدة اإلعتــراض ثالثــون يومــا‬\n‫ســتبدأ مــن ذلــك التاريــخ وأن عليــه أن يقــدم الئحتــه اإلعتراضيــه خاللهــا‬\n‫وأنهــا ان مضــت دون تقــدمي الئحتــه اإلعتراضيــه خاللهــا فــإن حقــه يف‬\n‫اإلســتئناف والتمييــز يســقط ويصبــح احلكــم قطعيــا مبضــي مــدة‬\n‫اإلعتــراض ففهــم ذلــك ‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم وردت املعاملــة مــن محكمــة اإلســتئناف‬\n‫باملنطقــة الشــرقية ومشــفوعها القــرار رقــم ‪ 33471559‬يف‬\n‫‪1433/12/1‬ه ـ ونــص احلاجــة منــه مــا يلــي ( لوحــظ مــا يلــي ‪ :‬أوال ‪/‬‬\n‫أن املدعــى عليــه ذكــر يف إجابتــه والالئحــة االعتراضيــة املرفقــة أنــه‬\n‫كان ينفــق علــى أوالده األربعــة الصغــار ولــم جنــد فضيلتــه قــد ناقــش‬\n‫ذلــك بــن الطرفــن وأجــرى حيالــه اإليجــاب الشــرعي وال بــد مــن ذلــك‪.‬‬\n‫ثانيــا ‪ /‬أن فضيلتــه لــم يتحقــق مــن أعمــار األوالد مــن واقــع إثبــات رســمي‬\n‫وال بــد مــن ذلــك ‪ .‬ثالثــا ‪ /‬أال يــرى فضيلتــه طلــب ميــن االســتظهار مــن‬\n‫املدعيــه علــى أنهــا أنفقــت بنيــة الرجــوع علــى املدعــى عليــه ‪ .‬فعلــى‬\n\n\n                                                                                       ‫‪114‬‬\n\f      ‫فضيلتــه مالحظــة مــا أشــير إليــه وإحلــاق مــا يجــد يف الصــك وضبطــه‬\n      ‫وســجله ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا ) وبعــرض مــا جــاء يف‬\n      ‫املالحظــة األولــى علــى الطرفــن قــال املدعــى عليــه لقــد انتقــل عنــدي‬\n      ‫ويف حضانتــي أوالدي األربعــه الصغــار وهــم ‪...‬و‪ ...‬و‪ ... ...‬ملــدة ســتة أشــهر‬\n      ‫مــن املــدة التــي طالبــت بهــا املدعيــه وقــد انفقــت عليهــم قبــل انتقالهــم لــي‬\n      ‫مــدة ثمانيــة أشــهر حيــث كنــت أســلمهم مبالــغ نقديــة خــال كل شــهر‬\n      ‫ســبعمائة ريــال ألنــي اســلمها علــى دفعــات لــكل واحــد منهــم كمــا‬\n      ‫أحضــر كســوتهم يف املناســبات كمــا كلفــت شــخصا مــن قرابتــي‬\n      ‫ليتواصــل مــع املدعيــه ليؤمــن لهــا وألوالدهــا جميــع مــا يحتاجــون إليــه‬\n      ‫مــن أغــراض منزليــه ولــوازم بقالــه فحضــر إليهــا فطردتــه هكــذا قــرر‬\n      ‫املدعــى عليــه وبســؤال املدعيــه عمــا ذكــره املدعــى عليــه قالــت ال صحــة‬\n      ‫ملــا ذكــره بــل انتقلــوا إلــى املدعــى عليــه مــدة ثالثــة أشــهر فقــط وقــد‬\n      ‫كنــت أحضــر عشــاءهم يف منــزل املدعــى عليــه ومــا ذكــره عــن تســليمه‬\n      ‫لــأوالد مبالــغ ماليــه غيــر صحيــح وميكــن للمحكمــة ســؤال األوالد‬\n      ‫أنفســهم فهــم جميعــا بالغــون ومكلفــون هــذه إفادتــي فســألت الطرفــن‬\n      ‫عــن أعمــار األوالد وطلبــت دفتــر العائلــة واإلثبــات الرســمية لهــم فقــدم‬\n      ‫املدعــى عليــه دفتــر عائلتــه وظهــر منــه أن ‪ ...‬مولــوده يف ‪1408/9/25‬ه ـ‬\n      ‫و‪ ...‬مــن مواليــد ‪1411/7/24‬ه ـ و‪ ...‬مــن مواليــد ‪1413/5/21‬ه ـ و‪...‬‬\n      ‫مولوده يف ‪1415/4/14‬هـ و‪ ...‬يف ‪1419/4/1‬هـ و‪ ...‬يف ‪1421/9/21‬هـ‬\n      ‫وقــد طلبــت مــن املدعــى عليــه اثبــات مــا يدعيــه مــن نفقــة أوالده للمــدة‬\n      ‫التــي أنكرتهــا املدعيــه فقــال املدعــى عليــه ليــس لــدي بينه ســوى األوالد‬\n      ‫أنفســهم وأطلــب ســماع مــا لديهــم وقــد وافقــت املدعيــه علــى احضارهــم‬\n      ‫وقــرر الطرفــان اكتفائهمــا مبــا يفيــد بــه األوالد وأنهمــا يقبــان مــا‬\n\n\n‫‪115‬‬\n\f‫يقرونــه ثــم يف يــوم الثالثــاء ‪1434/03/24‬ه ـ حضــر الطرفــان املدعيــة‪...‬‬\n‫وأحضــر الطرفــان األوالد األربعــة وهــم ‪...‬وهــو ســعودي بالســجل املدنــي‬\n‫رقــم ‪...‬و‪ ...‬وهــو ســعودي بالســجل املدنــي رقــم ‪...‬و‪ ...‬وهــي ســعودية‬\n‫بالســجل املدنــي رقــم ‪...‬و‪...‬وهــي ســعودية بالســجل املدنــي رقــم‪...‬‬\n‫وبســؤالهم عمــا لديهــم حــول مــن تولــى اإلنفــاق عليهــم فقالــوا جميعــا‬\n‫لقــد أقمنــا عنــد والدنــا ثالثــة أشــهر فقــط وكان ينفــق علينــا فيهــا أمــا‬\n‫غيرهــا فلــم يســلمنا شــيء هــذا مــا لدينــا فعرضــت علــى املدعيــة مــا جــاء‬\n‫يف املالحظــة الثالثــة املتعلقــه بنيتهــا وقــت اإلنفــاق فقالــت لقــد كنــت‬\n‫ناويــة عنــد اإلتفــاق عليهــم أن أرجــع علــى والدهــم بالنفقــة وال مانــع لــدي‬\n‫مــن احللــف علــى ذلــك ثــم قالــت واهلل العظيــم أنــي انفقــت علــى أوالدي‬\n‫املــدة التــي كانــوا فيهــا عنــدي بنيــة الرجــوع علــى والدهــم بهــا وواهلل‬\n‫العظيــم ان املبالــغ التــي ســلمتها يف نفقتهــم تزيــد علــى املبلــغ احملكــوم‬\n‫بــه واهلل علــى مــا أقــول شــهيد وبتأمــل مــا ســبق ظهــر أن األوالد األربعــة‬\n‫انتقلــوا إلــى حضانــة والدهــم املدعــى عليــه مــدة ثالثــة أشــهر وألن قــدر‬\n‫نفقــة األوالد األربعــة يف األشــهر الثالثــة تبلــغ اثنــي عشــر ألــف ريــال‬\n‫لــكل ذلــك تقــرر مــا يلــي ‪ :‬أوال‪ :‬عدلــت عــن احلكــم علــى املدعــى‬\n‫عليــه بتســليم مائــه وثمانيــه وســتني ألــف ريــال ( ‪ . ) 168.000‬ثانيــا‪:‬‬\n‫حكمــت عوضــا عــن ذلــك علــى املدعــى عليــه أن يســلم للمدعيــه مائــه‬\n‫وســته وخمســن ألــف ريــال بعــد حســم نفقــة األوالد األربعــة مــدة ثالثــة‬\n‫أشــهر لكونهــم يف حضانــة والدهــم املدعــى عليــه وبعــرض احلكــم علــى‬\n‫الطرفــن اعترضــت عليــه املدعيــة فأفهمتهــا بأنــه ســيتم تزويدهــا يــوم‬\n‫الســبت ‪1434/03/28‬ه ـ بصــورة مــن احلكــم لتقــدمي اعتراضهــا عليــه‬\n‫كمــا أفهمتهــا بــأن مــدة االعتــراض ثالثــون يومــا وأن عليهــا أن تقــدم‬\n\n\n                                                                                      ‫‪116‬‬\n\f      ‫الئحتهــا اإلعتراضيــه خاللهــا كمــا أفهمتهــا بأنــه إن مضــت هــذه املــده‬\n      ‫دون تقــدمي الئحــة إعتراضيــه فــإن حقهــا يف اإلســتئناف والتمييــز يســقط‬\n      ‫ويصبــح احلكــم يف حقهــا قطعيــا ففهمــت ذلــك أمــا املدعــى عليــه فقــد‬\n      ‫اســتمر علــى اعتراضــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم أنــه يف هــذا اليــوم االحــد املوافــق ‪/6 /11‬‬\n      ‫‪1434‬ه ـ مت تصفــح هــذه املعاملــة وتبــن أن مــدة االعتــراض للمدعيــة قــد‬\n      ‫انتهــت دون تقــدمي الئحــه بإعتراضهــا وبــذا انتهــى حقهــا يف االعتــراض‬\n      ‫علــى هــذا احلكــم مبوجــب املــادة الثامنــة والســبعني بعــد املائــة مــن نظــام‬\n      ‫املرافعــات الشــرعية وقــررت بعــث املعاملــة إلــى محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية لتدقيــق احلكــم العتــراض املدعــى عليــه وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434 /6 /11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n      ‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/1461216‬ش‪ 2‬وتاريــخ‬\n      ‫‪1434/6/17‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة‬\n      ‫الدمــام برقــم ‪ 34/20681‬وتاريــخ ‪1434/6/12‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ ‪ ....‬املســجل برقــم ‪33395847‬‬\n      ‫وتاريــخ ‪1433/8/27‬ه ـ اخلــاص بدعــوى‪ ... /‬ضــد‪ ... /‬يف قضيــة نفقــة‬\n      ‫وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك جواب ـ ًا‬\n      ‫علــى قرارنــا الســابق رقــم ‪/33471559‬ش‪/2‬ب يف ‪1433/12/1‬ه ـ‬\n      ‫قررنــا املصادقــة علــى حكــم فضيلتــه بعــد اإلجــراء األخيــر واهلل املوفــق‬\n      ‫وصلى اهلل على نبينا محمد وآله وصحبه وســلم حرر يف ‪1434/7/4‬هـ‬\n\n\n‫‪117‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":107,"source_page_end":117,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1ce44d36313c50ab7be5295783d26f2cfcbc7c7f871ae532070eaec042a63509","normalized_text_hash":"2420ee02a7223c66387b8c9dc9b8c05cc04dfe8871c54dde93b7e6fd1dad728e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p107-33395847"},{"id":"8fd7bee2-08a4-526f-8b96-d0ffdeac9141","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة عدة -مطالبة أم بنفقة أوالدها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء -احلكم للمطلقة بنفقة عدتها -احلكم بنفقة ماضية ومستقبلية لأوالد.","document_number":"33469973","case_number":"33398477","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/30","year":"1434","subject":"نفقة -نفقة عدة -مطالبة أم بنفقة أوالدها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء -احلكم للمطلقة بنفقة عدتها -احلكم بنفقة ماضية ومستقبلية لأوالد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/30 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33469973 :‬‬\n                    ‫َر ْق ُم الدعوى‪33398477 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 3418287‬تاريخه‪1434/1/20 :‬هـ‬\n\n\n\n ‫نفقــة ‪ -‬نفقــة عــدة ‪ -‬مطالبــة أم بنفقــة أوالدهــا املاضيــة واملســتقبلية‬\n ‫‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء ‪ -‬احلكــم للمطلقــة بنفقــة‬\n                   ‫عدتهــا ‪ -‬احلكــم بنفقــة ماضيــة ومســتقبلية لــأوالد‪.‬‬\n\n\n\n\n ‫قــال املــرداوي يف اإلنصــاف ‪( 360/9‬وعليــه يعنــي املطلــق نفقــة املطلقــة‬\n ‫الرجعيــة وكســوتها وســكناها كالزوجــة ســواء وأمــا البائــن بفســخ أو‬\n ‫ا فلهــا النفقــة والســكنى وإال فــا شــيء لهــا)‪.‬‬\n                                                   ‫طــاق فــإن كانــت حامـ ً‬\n\n\n\n\n ‫ادعــت املدعيــة ضــد املدعــى عليــه أنهــا كانــت زوجــة لــه وقــد طلقهــا‬\n ‫مبوجــب صــك الطــاق املشــار إليــه يف نــص القضيــة وقــد أجنبــت لــه‬\n ‫علــى فــراش الزوجيــة ثالثــة أوالد‪ ،‬وأن املدعــى عليــه حــن طالقــه لهــا لــم‬\n ‫ينفــق عليهــا وال علــى أوالدهــا وطالبــت املدعيــة بنفقــة أوالدهــا مــن تاريــخ‬\n ‫طالقهــا ‪1432/8/18‬ه ـ وكذلــك طالبــت بنفقــة لهــا أثنــاء العــدة‪ ،‬وقــد‬\n ‫أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أنــه ال مانــع لديــه مــن‬\n ‫تســليم النفقــة التــي تقدرهــا احملكمــة‪ ،‬وعليــه مت تقديــر النفقــة من قبل‬\n ‫قســم اخلبــراء باحملكمــة لــأوالد الثالثــة بســبعمائة ريــال شــهري ًا ونفقــة‬\n ‫عــدة املدعيــة خمســمائة ريــال شــهرياً‪ ،‬وقــررت املدعيــة عــدم قناعتهــا‬\n                                                                                        ‫‪118‬‬\n\f      ‫بالقــرار الصــادر مــن قســم اخلبــراء‪ ،‬وصدر حكم ناظر القضية بتســليم‬\n      ‫املدعيــة نفقــة عدتهــا لطالقهــا األول وطالقهــا الثانــي ومجموعهــا ألــف‬\n      ‫وخمســمائة ريــال ونفقــة أوالدهــا املاضيــة أحــد عشــر ألفـ ًا ومائتــي ريــال‬\n      ‫ونفقــة مســتقبلية ألوالدهــا ســبعمائة ريــال شــهريا‪ ،‬وقــررت املدعيــة عدم‬\n      ‫القناعــة بخصــوص نفقــة أوالدهــا وقنعــت بخصــوص نفقتهــا‪ ،‬وصــدر‬\n      ‫قــرار محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا (‪ )....‬القاضي يف احملكمة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 33398477‬وتاريــخ ‪1433/06/14‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 331066651‬وتاريــخ ‪1433/06/08‬ه ـ‬\n      ‫ففــي يــوم األحــد املوافــق ‪ 1433/11/28‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10 : 00‬وفيهــا حضــرت ‪ .....‬مينيــة باإلقامــة رقــم ‪ .....‬واملعــرف بهــا مــن‬\n      ‫قبــل أخيهــا ‪ .....‬مينــي باإلقامــة رقــم ‪ .....‬وادعــت علــى احلاضــر معهــا‬\n      ‫يف مجلــس القضــاء ‪ ......‬مينــي باإلقامــة رقــم ‪ ....‬قائلــة يف دعواهــا لقــد‬\n      ‫كنــت زوجــة للمدعــى عليــه وقــد طلقنــي مبوجــب الصــك الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪ 335424‬يف ‪1433/1/3‬ه ـ وقــد أجنبــت منــه‬\n      ‫علــى فــراش الزوجيــة أوالدي وهــم ‪ .....‬املولــود يف ‪1422/11/7‬ه ـ و‪.....‬‬\n      ‫املولــودة يف ‪1425/11/12‬ه ـ و‪ ........‬املولــود يف ‪1427/12/21‬ه ـ وألن‬\n      ‫املدعــى عليــه حــن طالقــه لــم ينفــق علــي وال علــى أوالده أطلــب احلكــم‬\n      ‫علــى املدعــى عليــه أن يدفــع لــي نفقتــي أثنــاء العــدة وأن تقــدر احملكمــة‬\n      ‫نفقــة ألبنائــي مســتقبلة علمــا أنــه لــم ينفــق علــى أوالدي مــن تاريــخ طالقــه‬\n‫‪119‬‬\n\f‫األول هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكرتــه‬\n‫املدعيــة يف دعواهــا كلــه صحيــح جملــة وتفصيــا وال مانــع لــدي مــن‬\n‫إعطــاء النفقــة التــي تقدرهــا احملكمــة هــذه إجابتــي فجــرى ســؤال‬\n‫املدعيــة مــن متــى لــم يدفــع املدعــى عليــه نفقــة لهــا وألوالدهــا فقالــت مــن‬\n‫تاريــخ الطــاق األول الــذي كان يف ‪1432/8/18‬ه ـ وبعــرض ذلــك علــى‬\n‫املدعــى عليــه صــادق عليــه فجــرت الكتابــة منــا لرئيــس هيئــة النظــر‬\n‫باحملكمــة لتقديــر نفقــة األوالد مبوجــب خطابنــا رقــم ‪331066651‬‬\n‫يف ‪1433/8/19‬ه ـ فوردنــا جــواب رئيــس هيئــة النظــر باحملكمــة برقــم‬\n‫‪ 331066651‬يف ‪1433/9/10‬ه ـ وهــذا نصــه بعــد املقدمــة (عليــه فقــد‬\n‫حضــر الطرفــان وجــرت مناقشــتهما وبعــد االطــاع علــى اخلطــاب املرفــق‬\n‫مــن جهــة عمــل املدعــى عليــه أن املذكــور يعطــى راتــب ‪ 2300‬شــهريا‬\n‫فإننــا نــرى أن تكــون نفقــة العــدة مبقــدار خمســمائة ريــال شــهريا كمــا‬\n‫نــرى أن تكــون نفقــة األوالد الثالثــة ســبعمائة ريــال شــهريا هــذا مــا‬\n‫جــرى تقريــره والســام عضــو هيئــة النظــر التوقيــع رئيــس هيئــة النظــر‬\n‫التوقيــع) وبعــرض مــا جــاء يف قــرار هيئــة النظــر علــى املدعيــة بــه لــم تقنــع‬\n‫بــه وذكــرت أن ظــروف املعيشــة صعبــة وأن ولدهــا يعانــي مــن مــرض يف‬\n‫أذنــه يتطلــب الذهــاب بــه للمستشــفى وقيمــة عالجــه شــهريا ثالثمائــة‬\n‫ريــال وابنتهــا تعانــي مــن التهــاب يف الرئــة وحتتــاج جللســات بخــار عنــد‬\n‫احلاجــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى مــا جــاء‬\n‫يف قــرار هيئــة النظــر وحيــث صــادق املدعــى عليــه أنــه لــم يدفــع للمدعيــة‬\n‫نفقــة أثنــاء عدتهــا يف فتــرة طالقهــا األول والثانــي وحيــث صــادق املدعــى‬\n‫عليــه أنــه لــم يدفــع كذلــك نفقــة ألوالده مــن تاريــخ طالقــه للمدعيــة‬\n‫مــن أول طــاق والــذي كان يف ‪1432/8/18‬ه ـ وملــا ذكــره أهــل العلــم‬\n\n\n                                                                                          ‫‪120‬‬\n\f      ‫رحمهــم اهلل تعالــى مــن أن البائــن ال نفقــة لهــا قــال املــرداوي يف اإلنصــاف‬\n      ‫(وعليــه ‪-‬يعنــي املطلــق‪ -‬نفقــة املطلقــة الرجعيــة وكســوتها وســكناها‬\n      ‫كالزوجــة ســواء وأمــا البائــن بفســخ أو طــاق فــإن كانــت حامــا فلهــا‬\n      ‫النفقــة والســكنى وإال فــا شــيء لهــا) ينظــر اإلنصــاف (اجلــزء التاســع‬\n      ‫ص ‪ )360‬لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه أن يدفــع‬\n      ‫لزوجتــه النفقــة أثنــاء عدتهــا لطالقهــا الرجعــي األول يف ‪1432/8/18‬ه ـ‬\n      ‫والثانــي يف ‪1432/8/25‬ه ـ لشــهر شــعبان ورمضــان وشــوال مــن عــام‬\n      ‫‪1432‬ه ـ ومجموعهــا ألــف وخمســمائة ريــال وأن يدفــع ألوالدهــا النفقــة‬\n      ‫مــن تاريــخ ‪1432/8/18‬ه ـ حتــى تاريــخ اليــوم ومجموعهــا أحــد عشــر‬\n      ‫ألفــا ومائتــا ريــال وأن يدفــع ألوالدهــا نفقــة مســتقبلية تقــدر بســبعمائة‬\n      ‫ريــال وبعــرض احلكــم علــى الطرفــن قنــع بــه املدعــى عليــه وقنعــت‬\n      ‫بــه املدعيــة بخصــوص نفقــة العــدة ولــم تقنــع بخصــوص نفقــة أبنائهــا‬\n      ‫وطلبــت االســتئناف وأجيبــت لطلبهــا وجــرى تســليمها نســخة مــن صــك‬\n      ‫احلكــم لتقــدمي اعتراضهــا عليــه وأفهمتهــا أن لهــا ثالثــن يومــا مــن تاريــخ‬\n      ‫اليــوم لتقــدمي االعتــراض وأنهــا إذا لــم تقــدم اعتراضهــا خــال هــذه‬\n      ‫املــدة ســقط حقهــا يف االســتئناف واكتســب احلكــم القطعيــة وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                 ‫يف ‪ 1433/11/28‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n      ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 33/1066651‬وتاريــخ ‪1434/1/14‬ه ـ‬\n\n\n‫‪121‬‬\n\f‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33469973‬وتاريــخ ‪1433/11/30‬ه ـ‬\n‫املتضمــن دعــوى املــرأة ‪ .....‬مينيــة اجلنســية ضــد ‪ .....‬مينــي اجلنســية يف‬\n‫نفقــة أوالدهــا ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا‬\n                              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،،،‬‬\n\n\n\n\n                                                                                   ‫‪122‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":118,"source_page_end":122,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b2bf757cac229d2e04e90bb08dbcf2046d7323b11b5c0c95ea7e22b1a7f647f8","normalized_text_hash":"58825278a8be0f7c643536b88786a5f79724465755ae5201748519d2fadd2356","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p118-33469973"},{"id":"1f5a4cb9-a026-530b-946f-611a36c0de01","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -املطالبة بنفقة ابن املاضية واملستقبلية -نفقة حمل -حلف املدعية على أنها ما زالت ترضع ابنها رضاعة طبيعية -إنفاق املدعية على حملها بنية الرجوع على والد احلمل -تقدير النفقة عن طريق قسم اخلبراء -لم يحضر املدعى عليه -حلف اليمن -احلكم على املدعى عليه بدفع نفقة احلمل والنفقة الشهرية املاضية واملستقبلية والكسوة املستقبلية .","document_number":"33407511","case_number":"32229340","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/10","year":"1434","subject":"نفقة -املطالبة بنفقة ابن املاضية واملستقبلية -نفقة حمل -حلف املدعية على أنها ما زالت ترضع ابنها رضاعة طبيعية -إنفاق املدعية على حملها بنية الرجوع على والد احلمل -تقدير النفقة عن طريق قسم اخلبراء -لم يحضر املدعى عليه -حلف اليمن -احلكم على املدعى عليه بدفع نفقة احلمل والنفقة الشهرية املاضية واملستقبلية والكسوة املستقبلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/10 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33407511 :‬‬\n                          ‫َر ْق ُم الدعوى‪32229340 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34347433‬تاريخه‪1434/11/3 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬املطالبــة بنفقــة ابــن املاضيــة واملســتقبلية ‪ -‬نفقــة حمــل ‪ -‬حلف‬\n      ‫املدعيــة علــى أنهــا مــا زالــت ترضــع ابنهــا رضاعــة طبيعيــة ‪ -‬إنفــاق‬\n      ‫املدعيــة علــى حملهــا بنيــة الرجــوع علــى والــد احلمــل ‪ -‬تقديــر النفقــة‬\n      ‫عــن طريــق قســم اخلبــراء ‪ -‬لــم يحضــر املدعــى عليــه ‪ -‬حلــف اليمــن‬\n      ‫‪ -‬احلكــم علــى املدعــى عليــه بدفــع نفقــة احلمــل والنفقــة الشــهرية‬\n                                  ‫املاضيــة واملســتقبلية والكســوة املســتقبلية ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه تعالــى ‪ ( :‬وإن كــن أوالت حمــل فأنفقــوا عليهــن حتــى يضعــن‬\n                                                                   ‫حملهــن ) ‪.‬‬\n                    ‫‪ .2‬قوله تعالى ‪ ( :‬فإن أرضعن لكم فآتوهن أجورهن ) ‪.‬‬\n      ‫‪ .3‬ملــا قــرره أهــل العلــم مــن أن للحامــل نفقــة احلمــل ‪ ،‬قــال يف الــروض‬\n      ‫املربــع ‪ ( :‬والبائــن بفســخ أو طــاق ثالثـ ًا أو علــى عــوض لهــا ذلــك ‪ ،‬أي‬\n      ‫ا ) قــال يف حاشــية الــروض‬   ‫النفقــة والكســوة والســكنى إن كانــت حامـ ً‬\n                                 ‫املربــع ‪ :‬قــال املوفــق وغيــره بإجمــاع أهــل العلــم ‪.‬‬\n      ‫‪ .4‬وملــا قــرره أهــل العلــم أيض ـ ًا ـ أن للمرضــع أجــرة الرضــاع ‪ .‬قــال يف‬\n      ‫الــروض املربــع ‪ ( :‬ولهــا أي للمرضعــة طلــب أجــرة املثــل لرضــاع ولدهــا‬\n              ‫ولــو أرضعــه غيرهــا مجان ـ ًا ألنهــا أشــفق مــن غيرهــا البنهــا ) ‪.‬‬\n\n\n\n‫‪123‬‬\n\f‫ادعــت املدعيــة بأنهــا كانــت زوجــة للمدعــى عليــه ثــم طلقهــا وهــي حامل‬\n‫وأجنبــت منــه ابن ـ ًا وطلبــت إلــزام املدعــى عليــه بدفــع نفقــة احلمــل حيــث‬\n‫كانــت يف منــزل والدهــا كمــا طلبــت إلزامــه بدفــع النفقــة املســتحقة‬\n‫لهــا مقابــل إرضــاع ابنــه رضاعــة طبيعيــة وإلزامــه بدفــع النفقــة املاضيــة‬\n‫واملســتقبلية‪ ،‬وقــد صــادق املدعــى عليــه علــى زواجــه مــن املــرأة املدعيــة‬\n‫وإجنابهــا منــه الولــد املذكــور وال مانــع لديــه مــن دفــع مــا يلزمــه شــرع ًا‬\n‫لهــا أو البنهــا مــع حتديــد خمــس ســاعات مــن كل أســبوع للزيــارة‪،‬‬\n‫وبعــرض ذلــك علــى املدعيــة رفضــت ذلــك وذكــرت أنهــا غيــر موافقــة‬\n‫علــى تســليمه ابنهــا لكــون ابنهــا مــا زال رضيعـ ًا ويحتــاج إلــى الرضاعــة‬\n‫خــال هــذه املــدة‪ ،‬لــذا جــرت الكتابــة لهيئــة النظــر لتقديــر النفقــة‬\n‫الالزمــة للمدعيــة وابنهــا وحتديــد الزيــارة‪ ،‬فأفــادت هيئــة النظــر أنــه‬\n‫قــد مت حتديــد موعديــن للمدعــى عليــه ولــم يحضــر‪ ،‬علمـ ًا بــأن املدعــى‬\n‫عليــه لــم يحضــر اجللســة الثانيــة لــدى احملكمــة‪ ،‬وقــد جــرت الكتابــة‬\n‫مــن هيئــة النظــر ملقــر عمــل املدعــى عليــه لالستفســار عــن راتبــه فــورد‬\n‫كتــاب الشــركة التــي يعمــل بهــا املدعــى عليــه يفيــد أن صــايف راتبــه‬\n‫فيهــا ‪ 4012‬ريــال‪ ،‬كمــا جــرى االطــاع علــى شــهادة امليــاد املؤقتــة‬\n‫لالبــن ـ جــرى ســؤال املدعيــة هــل مــا زالــت ترضعــن ابنــك رضاعــة‬\n‫طبيعيــة فقالــت نعــم فطلــب منهــا اليمــن علــى ذلــك فحلفــت‪ ،‬كمــا‬\n‫جــرى ســؤال املدعيــة هــل كنــت تنويــن الرجــوع علــى املدعــى عليــه‬\n‫بنفقــة احلمــل فأجابــت بنعــم‪ ،‬وقــد تعــذر تقديــر النفقــة املدعــى بهــا لعــدم‬\n‫حضــور املدعــى عليــه‪ ،‬وقــررت املــرأة نيتهــا الرجــوع علــى املدعــى عليــه‬\n\n                                                                                        ‫‪124‬‬\n\f      ‫بنفقــة احلمــل‪ ،‬وأدت املدعيــة اليمــن املطلوبــة‪ ،‬وألن األدلــة الشــرعية‬\n      ‫دلــت علــى وجــوب النفقــة علــى املرضــع حتــى تضــع حملهــا قــال تعالــى‬\n      ‫(وإن كــن أوالت حمــل فأنفقــوا عليهــن حتــى يضعــن حملهــن )‪ ،‬فقــد‬\n      ‫قــرر أهــل العلــم علــى أن للحامــل نفقــة احلمــل‪ ،‬كمــا قــرر أهــل العلــم‬\n      ‫أن للمرضــع أجــرة‪ ،‬لــذا مت احلكــم بإلــزام املدعــى عليــه بدفــع مبلــغ‬\n      ‫وقــدره خمســة آالف وأربعمائــة ريــال وميثــل نفقــة احلمــل للمدعيــة ملــدة‬\n      ‫تســعة أشــهر وإلــزام املدعــى عليــه بدفــع أجــرة الرضــاع للمدعيــة وقدرهــا‬\n      ‫خمســمائة ريــال اعتبــار ًا مــن ‪1432/4/29‬ه ـ حتــى ‪1434/4/29‬ه ـ مــا‬\n      ‫ال قبــل ســن الفطــام ألي ســبب كان‬      ‫لــم تتوقــف عــن الرضــاع مســتقب ً‬\n      ‫واحلكــم بإلــزام املدعــى عليــه بدفــع نفقــة البنــه وتســليمها للمدعيــة‬\n      ‫وقدرهــا مائتــي ريــال للفتــرة مــن ‪1432/4/29‬ه ـ حتــى ‪1434/4/29‬ه ـ‬\n      ‫وإلــزام املدعــي عليــه بدفــع نفقــة البنــه وتســليمها للمدعيــة وقدرهــا‬\n      ‫خمســمائة ريــال اعتبــار ًا مــن ‪1434/5/29‬ه ـ وإلــزام املدعــى عليــه بدفــع‬\n      ‫كســوة ســنوية البنــه للعيــد مقدراهــا خمســمائة ريــال تدفــع يف غــرة‬\n      ‫رمضــان مــن كل عــام اعتبــار ًا مــن شــهر رمضــان لعــام ‪1433‬ه ـ وإلــزام‬\n      ‫املدعــى عليــه بإصــدار شــهادة ميــاد البنــه وإضافتــه يف ســجل العائلــة‬\n      ‫وإفهــام املدعــى عليــه بــأن املطالبــة بالزيــارة تكــون بدعــوى مســتقلة إذا‬\n      ‫رغــب واعتبــار احلكــم حضوري ـ ًا يف حقــه وتبليــغ املدعــى عليــه بصــورة‬\n      ‫مــن إعــام احلكــم وإفهامــه بتعليمــات االســتئناف وصــدق احلكــم مــن‬\n                                                              ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪125‬‬\n\f‫احلمد هلل وحده وبعد فلدي أنا ‪ .....‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 32229340‬وتاريــخ ‪1432/06/14‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 32715036‬وتاريــخ ‪1432/06/14‬ه ـ‬\n‫ففــي يــوم االثنــن املوافــق ‪1432/10/21‬ه ـ أفتتحــت اجللســة وفيهــا‬\n‫حضــرت‪ ...‬مينيــة اجلنســية مبوجــب اإلقامــة رقــم (‪ ).....‬واملعــرف بهــا‬\n‫مــن قبــل أخيهــا ‪ ......‬مينــي اجلنســية مبوجــب اإلقامــة رقــم (‪ ).....‬وادعــت‬\n‫علــى احلاضــر معهــا‪ .....‬ســعودي اجلنســية يحمــل ســجل مدنــي رقــم (‪).....‬‬\n‫قائلــة يف دعواهــا عليــه ان هــذا احلاضــر هــو زوجــي ســابقا وقــد اجنبــت‬\n‫منــه ابن ـ ًا بتاريــخ ‪1432/4/29‬ه ـ وقــد طلقنــي بتاريــخ ‪ 1432/2/28‬ه ـ‬\n‫اطلــب إلزامــه بدفــع نفقــة احلمــل حيــث كنــت يف منــزل والــدي منــذ‬\n‫بدايــة احلمــل يف شــهر رجــب مــن عــام ‪1431‬ه ـ كمــا أطلــب إلزامــه‬\n‫بدفــع النفقــة املســتحقة لــي مقابــل إرضــاع ابنــه رضاعــة طبيعيــة وإلزامــه‬\n‫بدفــع النفقــة املاضيــة واملســتقبلية البنــه هــذه دعــواي وبســؤال املدعــى‬\n‫عليــه أجــاب قائــا مــا ذكرتــه املدعيــة يف دعواهــا كلــه صحيــح فقــد‬\n‫كانــت زوجتــي واجنبــت منــي ابنــا اســميته ‪ .....‬وال مانــع لــدي مــن دفــع‬\n‫مــا يلزمنــي شــرعا نفقــة للمدعيــة أو البنــي لكــن أطلــب حتديــد زيــارة ال‬\n‫تقــل عــن خمــس ســاعات يف كل أســبوع وإلــزام املدعيــة بتســليمي ابنــي‬\n‫وقــت الزيــارة هــذه إجابتــي وبعــرض ذلــك علــى املدعيــة أجابــت اننــي غيــر‬\n‫موافقــه علــى تســليمه ابنــه ملــدة خمــس ســاعات لكــون ابنــي يرضــع‬\n‫رضاعــة طبيعيــة وال يتحمــل البقــاء مــدة خمــس ســاعات دون رضــاع‬\n\n                                                                                     ‫‪126‬‬\n\f      ‫ثــم قــررت رفــع اجللســة والكتابــة لهيئــة النظــر لتقديــر النفقــة الالزمــة‬\n      ‫للمدعيــة وابنهــا وحتديــد الزيــارة ورفعــت اجللســة حلــن ورود اجلــواب ويف‬\n      ‫يــوم االثنــن املوافــق ‪1433/5/24‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n      ‫املدعيــة املعــرف بهــا مــن قبــل أخيهــا ‪ .....‬املذكــور ســابقا ولــم يحضــر‬\n      ‫املدعــى عليــه يف هــذه اجللســة ولــم يــرد مــن محضــر احملكمــة مــا يفيــد‬\n      ‫تبلــغ املدعــى عليــه مبوعــد اجللســة وجــرت الكتابــة لهيئــة النظــر لتقديــر‬\n      ‫النفقــة املدعــى بهــا فوردنــا خطــاب رئيــس هيئة النظر رقــم ‪32/715036‬‬\n      ‫يف ‪1433/3/23‬ه ـ والــذي جــاء فيــه أنــه قــد مت حتديــد موعديــن مــن‬\n      ‫قبــل الهيئــة املوعــد األول يف يــوم الثالثــاء املوافــق ‪1433/3/8‬ه ـ واملوعــد‬\n      ‫الثانــي يف يــوم االثنــن املوافــق ‪1433/3/21‬ه ـ ولــم يحضــر املدعــى عليــه‬\n      ‫يف كال املوعديــن وقــد تعــذر اكمــال الــازم وباالطــاع علــى مرفقــات‬\n      ‫خطــاب رئيــس هيئــة النظــر جــرى االطــاع علــى ورقــة تبليــغ باحلضــور‬\n      ‫للمحكمــة للموعــد احملــدد لــدى هيئــة النظــر وقــد تبلــغ املدعــى عليــه‬\n      ‫مبوعــد اجللســة وكذلــك املوعــد االخــر احملــدد بتاريــخ ‪1432/11/18‬هـ‬\n      ‫لــدى هيئــة النظــر ولــم يحضــر املدعــى عليــه وقــد جرت الكتابــة من قبل‬\n      ‫رئيــس هيئــة النظــر إلــى ‪ ...‬وهــي التــي يعمــل لديهــا املدعــى عليــه فــوردت‬\n      ‫االجابــة مــن ‪ ...‬بــان صــايف راتــب املدعــى عليــه اربعــة األف واثنــا عشــر‬\n      ‫ريــاال كمــا جــرى االطــاع علــى شــهادة امليــاد املؤقتــة البــن املدعى عليه‬\n      ‫وهــو مولــود بتاريــخ ‪1432/4/29‬ه ـ فجــرى ســؤال املدعيــة هــل كانــت‬\n      ‫تنــوي وهــي حامــل الرجــوع عليــه يف نفقــة احلمــل فأجابــت نعــم كنــت‬\n      ‫أنــوي الرجــوع عليــه يف نفقــة احلمــل فجــرى ســؤالها هــل مــا زالــت ترضــع‬\n      ‫ابنهــا مــن لبنهــا فأجابــت نعــم إننــي مــا زلــت أرضعــه مــن لبنــي فطلبــت‬\n      ‫منهــا اليمــن علــى ذلــك فحلفــت قائلــة واهلل العظيــم إننــي مــا زلــت أرضــع‬\n\n\n‫‪127‬‬\n\f‫ابنــي ‪ ...‬مــن لبنــي ولــم افطمــه بعــد فبنــاء علــى ما ســبق من دعــوى املدعية‬\n‫وإجابــة املدعــى عليــه املتضمنــة املصادقــة علــى دعــوى املدعيــة وبنــاء‬\n‫علــى خطــاب رئيــس هيئــة النظــر املتضمــن تعــذر تقديــر النفقــة املدعــى‬\n‫بهــا لعــدم حضــور املدعــى عليــه وبنــاء علــى مــا قررتــه املدعيــة مــن نيتهــا‬\n‫الرجــوع علــى املدعــى عليــه بنفقــة احلمــل وألدائهــا اليمــن املطلوبــة منهــا‬\n‫ملــا ذكــرت مــن أنهــا مــا زالــت ترضــع ابنهــا مــن لبنهــا ولقولــه تعالــى (وإن‬\n‫كــن أوالت حملــن فأنفقــوا عليهــن حتــى يضعــن حملهــن) وقولــه تعالــى‬\n‫(فــإن أرضعــن لكــم فآتوهــن أجورهــن) وملــا قــرره أهــل العلــم مــن أن‬\n‫للحامــل نفقــة احلمــل قــال يف الــروض املربــع‪( :‬والبائــن بفســخ أو طــاق‬\n‫ثالثــا أو علــى عــوض لهــا ذلــك‪ ،‬أي النفقــة والكســوة والســكنى إن‬\n‫كانــت حامــا‪ .‬قــال يف احلاشــية‪ :‬قــال املوفــق وغيــره بإجمــاع أهــل العلــم‪.‬‬\n‫وملــا قــرره أهــل العلــم أيضــا‪ :‬مــن أن للمرضــع أجــرة الرضــاع قــال يف‬\n‫الــروض املربــع‪ :‬ولهــا أي للمرضعــة طلــب أجــرة املثــل لرضــاع ولدهــا‬\n‫ولــو أرضعــه غيرهــا مجانــا ألنهــا أشــفق مــن غيرهــا البنهــا) لذلــك كلــه‬\n‫فقــد قــررت مــا يلــي ‪ :‬أو ًال ألزمــت املدعــى عليــه بدفــع خمســة أالف‬\n‫وأربعمائــة ريــال وميثــل مــا يلزمــه شــرع ًا مــن نفقــة احلمــل للمدعيــة ملــدة‬\n‫تســعة أشــهر ثاني ـ ًا ألزمــت املدعــى عليــه بدفــع أجــرة الرضــاع للمدعيــة‬\n‫وقدرهــا خمســمائة ريــال شــهري ًا اعتبــار ًا مــن ‪1432/4/29‬ه ـ وحتــى‬\n‫ال قبــل ســن الفطــام‬   ‫‪1434/4/29‬ه ـ مالــم تتوقــف عــن الرضــاع مســتقب ً‬\n‫ألي ســبب كان ثالثـ ًا ألزمــت املدعــى عليــه بدفــع نفقــة البنــه وتســليمها‬\n‫للمدعيــة وقدرهــا مائتــي ريــال شــهري ًا للفتــرة مــن ‪1432/4/29‬ه ـ‬\n‫وحتــى ‪1434/4/29‬ه ـ رابع ـ ًا ألزمــت املدعــى عليــه بدفــع نفقــة شــهرية‬\n‫ألبنــه وتســليمها للمدعيــة وقدرهــا خمســمائة ريــال شــهري ًا اعتبــار ًا مــن‬\n\n\n                                                                                         ‫‪128‬‬\n\f      ‫‪1434/5/29‬هـ خامسـ ًا الزمت املدعى عليه بدفع كســوة ســنوية البنه‬\n      ‫للعيــد وقدرهــا خمســمائة ريــال تدفــع يف غــرة شــهر رمضــان مــن كل‬\n      ‫عــام اعتبــار ًا مــن شــهر رمضــان لعــام ‪1433‬ه ـ سادس ـ ًا الزمــت املدعــى‬\n      ‫عليــه باصــدار شــهادة ميــاد البنــه وأضافتــه يف ســجل العائلــة وبذلــك‬\n      ‫حكمــت وجعلــت للمدعــى عليــه املطالبــة بالزيــارة بدعــوى مســتقلة متــى‬\n      ‫رغــب وقــررت اعتبــار احلكــم حضوريـ ًا يف حــق املدعــى عليــه ومت اعــان‬\n      ‫احلكــم بتاريــخ ‪1433/6/14‬ه ـ وقــررت إبــاغ املدعــى عليــه بصــورة مــن‬\n      ‫اعــام احلكــم وأفهامــه بــان لــه التقــدم بالئحــة اعتراضيــة خــال ثالثــن‬\n      ‫يومــا مــن تاريــخ اســتالم نســخة مــن اعــام احلكــم وإذا لــم يقــدم الالئحــة‬\n      ‫خــال املــدة املقــررة فــان حقــه باالعتــراض يســقط ويكتســب احلكــم‬\n      ‫القطعيــة وصلــى اهلل علــى نبينــا محمــد وســلم ‪.‬حــرر يف ‪1433/6/14‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n      ‫املكرمــة ففــي يــوم األربعــاء املوافــق‪ 1434/11/26‬ه ـ افتتحــت‬\n      ‫اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا الصــك‬\n      ‫وقــد ظهــر عليــه باملوافقــة ونصــه تظهيــرات الدائــرة الثالثــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا وبيــوت املــال مبحكمــة االســتئناف‬\n                                                                 ‫مبكــة املكرمــة ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33407511‬‬\n      ‫وتاريــخ ‪1433/9/10‬ه ـ الصــادر مــن فضيلــة الشــيخ واصدرنــا القــرار‬\n      ‫رقــم ‪ 34347433‬يف ‪1434/11/3‬ه ـ املتضمــن باألكثريــة املوافقــة على‬\n      ‫احلكــم مــع مالحظــة التنبيــه املرفــق مــن عضــو عضــو رئيــس الدائــرة‬\n      ‫وحتــى ال يخفــى جــرى إحلاقــة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/26‬ه ـ‬\n\n\n‫‪129‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 32/715036‬وتاريــخ ‪1434/10/12‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33407511‬وتاريــخ ‪1433/9/10‬هــ‪،‬‬\n‫املتضمــن دعــوى املــرأة مينيــة اجلنســية ضــد يف نفقــة ‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم مــع مالحظــة‬\n‫التنبيــه املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                     ‫وصحبــه وســلم ‪،،،،،،‬‬\n\n\n\n\n                                                                                      ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":123,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5a1e6f97733244eea42b9383a0d881f4f364d9f07da7f7be1ea702e51fa5d0bf","normalized_text_hash":"5a984fba17005e8ae0ae0cc098a6118ef82ac8471161a36713a07aea21b43c91","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p123-33407511"},{"id":"5d55a765-5a80-5ffb-ae4e-08d7ae7cde18","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقه -نفقه االبن املاضية -للمنفق الرجوع على الزوج والقريب مبا أنفقه إذا نوى الرجوع -تقدير النفقة املاضية عن طريق قسم اخلبراء -حلف اليمن من الزوجة -اإلقرار من الزوج بعدم اإلنفاق -احلكم بإلزام الزوج بنفقة االبن املاضية .","document_number":"33420807","case_number":"32229964","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/9","year":"1434","subject":"نفقه -نفقه االبن املاضية -للمنفق الرجوع على الزوج والقريب مبا أنفقه إذا نوى الرجوع -تقدير النفقة املاضية عن طريق قسم اخلبراء -حلف اليمن من الزوجة -اإلقرار من الزوج بعدم اإلنفاق -احلكم بإلزام الزوج بنفقة االبن املاضية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/10/9 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33420807 :‬‬\n                          ‫َر ْق ُم الدعوى‪32229964 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34192684‬تاريخه‪1434/4/20 :‬هـ‬\n\n\n\n      ‫نفقــه ‪ -‬نفقــه االبــن املاضيــة ‪ -‬للمنفــق الرجــوع علــى الــزوج والقريــب‬\n      ‫مبــا أنفقــه إذا نــوى الرجــوع ‪ -‬تقديــر النفقــة املاضيــة عــن طريــق‬\n      ‫قســم اخلبــراء ‪ -‬حلــف اليمــن مــن الزوجــة ‪ -‬اإلقــرار مــن الــزوج بعــدم‬\n                      ‫اإلنفــاق‪ -‬احلكــم بإلــزام الــزوج بنفقــة االبــن املاضيــة ‪.‬‬\n\n\n\n\n      ‫جــاء يف شــرح املنتهــى ‪( 242/3‬ولــو امتنــع منهــا أي النفقــة زوج أو قريــب‬\n      ‫فأنفــق عليهمــا غيــره رجــع منفــق علــى زوجــة أو قريــب بنيــة رجــوع ألن‬\n      ‫االمتنــاع قــد يكــون لضعــف مــن وجبــت لــه وقــوة مــن وجبــت عليــه فلــو‬\n                                   ‫لــم ميلــك املنفــق الرجــوع لضــاع الضعيــف)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بــأن موكلتــه كانــت زوجــة‬\n      ‫للمدعــى عليــه وقــد أجنبــت منــه ابن ـ ًا ثــم طلقهــا بتاريخ‪1420/5/14‬ه ـ‬\n      ‫وبقــي االبــن يف حضانــة موكلتــه مــن تاريــخ طالقهــا إلــى أن اســتلمه‬\n      ‫املدعــى عليــه يف ‪1429/9/15‬ه ـ ولــم ينفــق عليــه املدعــى عليــه فتــرة‬\n      ‫بقائــه لــدى موكلتــه وقــد أنفقــت موكلتــه عليــه بنيــة الرجــوع علــى‬\n      ‫املدعــى عليــه ويطلــب تقديــر النفقــة املاضيــة وإلــزام املدعــى عليــه‬\n\n‫‪131‬‬\n\f‫بتســليمها ملوكلتــه هكــذا ادعــى ‪ -‬صــادق املدعــى عليــه علــى الدعــوى‬\n‫ماعــدا إنفاقهــا علــى االبــن فأنكــره وأن الــذي ينفــق عليــه هــو والدهــا‬\n‫وأخبــره بأنــه متبــرع بالنفقــة‪ ،‬لكــن أنكــرت املدعيــة إنفــاق والدهــا‬\n‫علــى االبــن‪ ،‬وحضــر والــد املدعيــة وأنكــر إنفاقــه علــى االبــن وقــرر بــأن‬\n‫املدعيــة هــي مــن تنفــق عليــه ‪،‬لــذا حلفــت املدعيــة اليمــن بعــد طلبهــا‬\n‫منهــا علــى إنفاقهــا علــى اإلبــن ‪ -‬جــرى الكتابــة لقســم اخلبــراء لتقديــر‬\n‫النفقــة املاضيــة البــن املدعيــة ‪ -‬ورد قرارهــم بــأن مقــدار النفقــة الشــهرية‬\n‫عــن الفتــرة املاضيــة ثالثمائــة ريــال ‪ -‬ومبــا أن املدعــى عليــه أقــر بأنــه‬\n‫لــم ينفــق علــى ابنــه أثنــاء الفتــرة املذكــورة يف الدعــوى ‪ -‬وملــا جــاء يف‬\n‫شــرح املنتهــى ‪ ( 242/‬ولــو امتنــع منهــا أي النفقــة زوج أو قريــب فأنفــق‬\n‫عليهمــا غيــره رجــع منفــق علــى زوجــة‪ ،)..‬وملــا تقــدم احلكــم بإلــزام‬\n‫املدعــى عليــه بتســليم مبلــغ وقــدره ثالثــة وثالثــون ألف ـ ًا وســتمائة ريــال‬\n‫للمدعية‪،‬واعتــرض الطرفــان علــى احلكــم بالئحــة وصــدق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد ‪ ،‬فلــدي أنــا ‪ ........‬القاضــي باحملكمــة العامــة‬\n‫بالريــاض ففــي يــوم الثالثــاء املوافق‪1432/10/15‬ه ـ حضــر ‪........‬‬\n‫حامــل الســجل املدنــي رقــم ‪ ........‬بالوكالــة عــن ‪ ........‬حاملــة الســجل‬\n‫املدنــي رقــم ‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بالطائــف برقــم ‪ 43812‬يف ‪1429/8/25‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫‪ ........‬حامــل الســجل املدنــي رقــم ‪ ........‬قائــا يف دعــواه ‪ :‬إن موكلتــي‬\n‫كانــت زوجــة للمدعــى عليــه تزوجهــا بتاريــخ ‪1418/4/6‬ه ـ وقــد رزق‬\n\n                                                                                      ‫‪132‬‬\n\f      ‫منهــا بابــن اســمه ‪ ........‬ثــم طلقهــا بتاريــخ ‪1420/5/14‬ه ـ وبقــي االبــن‬\n      ‫يف حضانــة موكلتــي مــن تاريــخ طالقهــا إلــى أن اســتلمه املدعــى عليه يف‬\n      ‫‪1429/9/15‬ه ـ ولــم ينفــق عليــه املدعــى عليــه أثنــاء بقائه لــدى موكلتي‬\n      ‫وقــد أنفقــت عليــه موكلتــي طيلــة فتــرة بقائــه لديهــا ناويــة الرجــوع علــى‬\n      ‫املدعــى عليــه مبــا أنفقــت وأطلــب تقديــر نفقــة ذلــك االبــن عــن الفتــرة‬\n      ‫التــي بقــي فيهــا لــدى موكلتــي وإلــزام املدعــى عليــه بتســليمها ملوكلتــي‬\n      ‫هــذه دعــواي ‪ ،‬وباســتجواب املدعــى عليــه قــال ‪ :‬مــا ذكــره املدعــي‬\n      ‫مــن أن موكلتــه كانــت زوجــة لــي تزوجتهــا يف ‪1418/4/6‬ه ـ ورزقــت‬\n      ‫منهــا بابــن اســمه ‪ ...‬ثــم طلقتهــا بتاريــخ ‪1420/5/14‬ه ـ وبقــي االبــن يف‬\n      ‫حضانــة املدعيــة مــن تاريــخ طالقهــا إلــى أن اســتلمته يف ‪1429/9/15‬ه ـ‬\n      ‫وأننــي لــم أنفــق عليــه أثنــاء تلــك الفتــرة فصحيــح وأمــا مــا ذكــره مــن‬\n      ‫أن موكلتــه أنفقــت عليــه تلــك الفتــرة فغيــر صحيــح والصحيــح أن‬\n      ‫الــذي كان ينفــق عليــه هــو والدهــا وهــو عمــي وقــد أخبرنــي أنــه متبــرع‬\n      ‫بالنفقــة هكــذا أجــاب ‪ ،‬فطلبــت مــن املدعــي أن يبــن مقــدار مــا أنفقتــه‬\n      ‫موكلتــه علــى ابنهــا خــال الفتــرة املذكــورة يف الدعــوى فوعــد بذلــك‬\n      ‫ويف يــوم األربعــاء املوافــق ‪1433/3/9‬ه ـ حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه فســألت املدعــي وكالــة عــن مقــدار مــا أنفقتــه موكلتــه علــى ابنها‬\n      ‫خــال الفتــرة املذكــورة يف الدعــوى فقــال إنــه اليقــل عــن ســتة وخمســن‬\n      ‫ألــف ريــال وأمــا ماذكــره املدعــى عليــه مــن أن الــذي كان ينفــق علــى‬\n      ‫ابــن موكلتــي هــو والدهــا وأنــه أخبــره أنــه متبــرع بالنفقــة فغيــر صحيــح‬\n      ‫فســألت املدعــى عليــه هــل لديــه بينــة علــى أن الــذي كان ينفــق علــى ابنــه‬\n      ‫هــو والــد املدعيــة فقــال إنــه أخبرنــي بذلــك وأنــه متبــرع بذلــك بحضــور‬\n      ‫عــدد مــن الشــهود فطلبــت مــن املدعــي وكالــة إحضــار املدعيــة ووالدهــا‬\n\n\n‫‪133‬‬\n\f‫‪ .‬ويف يوم الســبت املوافق‪1433/07/19‬هـ حضرت املدعية أصالة ‪........‬‬\n‫حامــل الســجل املدنــي رقــم ‪ ........‬ووكيلهــا كمــا حضــر املدعــى عليــه‬\n‫كمــا حضــر والــد املدعيــة ‪ ........ ........‬حامــل الســجل املدنــي رقــم ‪........‬‬\n‫فجــرى عــرض ماذكــره املدعــى عليــه مــن أن الــذي كان ينفــق على ابنه‬\n‫هــو والــد املدعيــة علــى املدعيــة ووالدهــا فقالــت املدعيــة ‪ :‬إننــي أنــا التــي‬\n‫كنــت أنفــق علــى ابنــي ‪ ........‬وليــس والــدي ‪ .‬هكــذا قــررت كمــا قــال‬\n‫والــد املدعيــة ‪ ........‬إننــي لــم أكــن أنفــق علــى ابــن املدعــى عليــه ‪........‬‬\n‫وإمنــا كانــت تنفــق عليــه والدتــه املدعيــة هكــذا قــرر فجــرى عــرض‬\n‫اليمــن علــى املدعيــة فقالــت إننــي ســأحلف علــى أننــي أنفقــت عليــه مــاال‬\n‫يقــل عــن أربعــة وأربعــن ألفـ ًا وثمامنائــة ريــال ثــم حلفــت قائلــة ‪ :‬واهلل الــذي‬\n‫ال إلــه اال هــو إننــي قــد أنفقــت علــى ابنــي ‪ ........‬خــال فتــرة بقائــه لــدي‬\n‫مــن تاريــخ ‪1420/05/14‬ه ـ إلــى تاريــخ ‪1429/09/15‬ه ـ مــاال يقــل عــن‬\n‫أربعــة وأربعــن ألفـ ًا وثمامنائــة ريــال ناويــة الرجــوع بهــا علــى والــده املدعــى‬\n‫عليــه ‪ .‬هكــذا حلفــت فقــررت الكتابــة لقســم اخلبــراء لتقديــر النفقــة‬\n‫البــن املدعيــة خــال الفتــرة املذكــورة يف الدعــوى ‪ .‬ويف يــوم اإلثنــن‬\n‫املوافــق‪ 1433/10/09‬ه ـ حضــر وكيــل املدعيــة كمــا حضــر املدعــى‬\n‫عليــه‪ ،‬وقــد وردنــي قــرار مكتــب الصلــح رقــم» ‪ 723‬يف ‪1433/9/20‬ه ـ‬\n‫وقــد تضمــن مــا نصــه ‪« :‬مت االجتمــاع بالوكيــل الشــرعي للمدعيــة ‪........‬‬\n‫حســب صــورة الوكالــة الشــرعية املرفقــة‪ ،‬وكذلــك باملدعــى عليــه‬\n‫حيــث ذكــر املدعــي وكالــة بــأن موكلتــه تطالــب بنفقــة ابنهــا الســابقة‬\n‫مــن تاريــخ ‪1420/5/14‬ه ـ حتــى تاريــخ ‪1429/9/15‬ه ـ ‪ ،‬وأن املدعــى‬\n‫عليــه تقاعــد ويصــرف لــه معــاش تقاعــدي‪ ،‬وأنــه يقــوم مبزاولــة البيــع‬\n‫والشــراء يف الســيارات وكذلــك يف العقــار‪ ،‬أمــا بالنســبة للمدعــى عليــه‬\n\n\n                                                                                            ‫‪134‬‬\n\f      ‫فقــد ذكــر بأنــه ليــس لديــه مانــع مــن دفــع نفقــة ابنــه الســابقة حســب مــا‬\n      ‫تقــرره اللجنــة وأنــه ال يوجــد لديــه دخــل مــادي ســوى مــا يصــرف لــه مــن‬\n      ‫مصلحــة معاشــات التقاعــد‪ ،‬وجتــدون إقــرار كال منهمــا بطــي املعاملــة‬\n      ‫وبنــاء علــى ذلــك وبعــد اجللــوس مــع الطرفــن والتأمــل يف الوضــع املــادي‬\n      ‫للمدعــى عليــه حيــث اتضــح أنــه يتقاضــى معــاش تقاعــدي قــدره ‪2582‬‬\n      ‫ريــال وكذلــك يوجــد عليــه قســط شــهري قــدره ‪ 625‬ريــال لصالــح‬\n      ‫البنــك ‪ ........‬حســب كشــف احلســاب املرفــق ولــم يثبــت لدينــا خــاف‬\n      ‫ذلــك فإننــا نــرى أن تكــون نفقــة ابــن املدعيــة يف الفتــرة املشــار إليهــا‬\n      ‫‪ 300‬ريــال عــن كل شــهر مــاض» ا‪.‬ه ـ وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة‪ ،‬ومبــا أن املدعــى عليــه أقــر بأنــه لــم يكــن ينفــق علــى ابنــه‬\n      ‫أثنــاء الفتــرة املذكــورة يف الدعــوى وبنــاء علــى ميــن املدعيــة؛ لــذا فقــد‬\n      ‫حكمــت علــى املدعــى عليــه بــأن يســلم للمدعيــة أصالــة ثالثــة وثالثــن‬\n      ‫ألفــا وســتمائة ريــال وبعــرض احلكــم علــى الطرفــن قررا عــدم القناعة‪،‬‬\n      ‫وطلبــا االســتئناف‪ ،‬فأجبتهمــا لطلبهمــا وقــررت تســليم كل واحــد‬\n      ‫منهمــا صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه خــال مــدة‬\n      ‫ال تتجــاوز ثالثــن يومــا فمــن تأخــر منهمــا عــن ذلــك ســقط حقــه يف تقــدمي‬\n      ‫الالئحــة االعتراضيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/09‬هــ‪ .‬احلمــد هلل وحــده‬\n      ‫وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/02/19‬هـ فتحت اجللســة الســاعة‬\n      ‫‪ 10:45‬وفيهــا حضــر املدعــي وكالــة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 347833‬يف ‪1434/01/11‬ه ـ وقــد‬\n      ‫جــاء فيــه مــا نصــه (لوحــظ اآلتــي‪ :‬أوالً‪ /‬املدعيــة تطالــب بنفقــة ابنتهــا‬\n      ‫مــن تاريــخ طالقهــا إلــى أن اســتلمه املدعــي عليــه وهــذه نفقــة ماضيــة‬\n\n\n‫‪135‬‬\n\f‫ولــم جنــد أن فضيلتــه راجــع املســألة يف كالم أهــل العلــم‪ .‬ثاني ـاً‪/‬أال‬\n‫يــرى فضيلتــه عــرض الصلــح بينهمــا وترغيبهمــا يف ذلــك ملــا فيــه مــن‬\n‫قطــع اخلصومــة وإزالــة اخلــاف) وجوابــا علــى املالحظــة األولــى أقــول‪:‬‬\n‫إن كالم أهــل العلــم يــدل علــى مــا حكمــت بــه قــال يف شــرح املنتهــى‬\n‫‪( 242/3‬ولــو امتنــع منهــا أي النفقــة زوج أو قريــب فأنفــق عليهمــا غيــره‬\n‫رجــع منفــق علــى زوجــة أو قريــب بنيــة رجــوع ألن االمتنــاع قــد يكــون‬\n‫لضعــف مــن وجبــت لــه وقــوة مــن وجبــت عليــة فلــو لــم ميلــك املنفــق الرجــوع‬\n‫لضــاع الضعيــف ) وجوابــا علــى املالحظــة الثانيــة فقــد رفــض املدعــي‬\n‫وكالــة الصلح‪.‬لــذا لــم يظهــر لــي خــاف مــا حكمــت بــه وقــررت إعــادة‬\n‫املعاملــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/19‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 34186453‬وتاريــخ ‪1434/3/4‬ه ـ املرفــق بهــا‬\n‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ........ /‬برقــم‬\n‫‪ 33420807‬وتاريــخ ‪1433/10/9‬ه ـ اخلــاص بدعــوى‪ ........ /‬الوكيــل‬\n‫عــن ‪ ........‬ضــد‪ ........ /‬يف قضيــة نفقــة أوالد ‪ ،‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مباهــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصــك‬\n‫وصــورة ضبطــه والالئحتــن االعتراضيتــن وأوراق املعاملــة وباإلطــاع‬\n‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا‬\n‫رقــم ‪ 347833‬وتاريــخ ‪1434/1/11‬ه ـ تقــرر الدائــرة املصادقــة علــى‬\n‫احلكــم بعــد اجلــواب األخيــر ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمد‬\n                                                        ‫و علــى آلــه وصحبــه وســلم‬\n                                                                                        ‫‪136‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":131,"source_page_end":136,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6d85c1bf5f8a97c36405ea69a20860205aaad1d08c1a64808fb0f257cda760ff","normalized_text_hash":"ec191ea692a094c1d89dd8096476fe4b3a487448fb09da97662575a20d244e0f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p131-33420807"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

